quests[82017] = { id = 82017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verschmelzung von Alpträumen", description = "Die Aura des Schreckens, die Ihr erlebt habt, stammt nicht von einem Ort, sondern von einer Kreatur, einer besonders tödlichen Kreatur der Finsternis, einer verzerrten Schattenreflexion der schlimmsten Aspekte unserer Welt, die zu einem reinem Alptraum verschmolzen sind. Ich kann nicht sagen, woher ich das weiß, aber... ich habe davon geträumt. Oder besser gesagt: Es wurde mir gezeigt. Das ist schwer zu erklären. Bitte geht nach Moonglade und sprecht mit dem Druiden Loganaar. Vielleicht können wir die Kreatur noch aufhalten, bevor sie zu mächtig wird.", sourceObjective = "Sucht Loganaar in Moonglade auf", completion = "Das sind höchst beunruhigende Nachrichten. Wenn es so ist, wie Hannalah gesagt hat, wird die aktuelle Krise im Traum noch viel schlimmer werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82018] = { id = 82018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Itharius", description = "Ist Euch der Tempel von Atal'Hakkar ein Begriff? Er hat eine sagenumwobene Geschichte, die ich hier nicht ausführen will, doch er steht im Augenblick unter der Verwaltung einer großen Gruppe mächtiger grüner Drachen. Der Hauptwächter des Tempels ist ein großer Drache namens Eranikus, der besonders auf den Traum eingestimmt ist. Ich hoffe, dass er uns helfen kann. Geht in die Sümpfe des Elends und sucht dort den Waldläufer Itharius auf. Er mag wissen, wie wir Eranikus um Hilfe ansprechen können.", sourceObjective = "Sucht Itharius irgendwo in den Sümpfen des Elends auf.", progress = "Seid gegrüßt, {race}.", completion = "Ihr wollt Eranikus aufsuchen? Eure Ankunft ist womöglich schlecht abgepasst, {class}. Ich fürchte, im Tempel von Atal'Hakkar stimmt etwas nicht. Kommt, unterhalten wir uns weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[82019] = { id = 82019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergehen", description = "Zu seiner Zeit war der sogenannte Versunkene Tempel die Heimat einer Trollsekte, die es sich zum Ziel gesetzt hatte, ihre uralte Blutgottheit Hakkar den Seelenschinder wiederzuerwecken. Ehe die Atal'ai diese furchtbaren Ambitionen erkennen konnten, stieß Yseras Zorn den Tempel in den Schlamm und ließ den Drachen Eranikus mit seiner Gruppe als Wächter zurück. In letzter Zeit habe ich viel darüber gehört, dass die Trolle dort wieder aktiv geworden sein sollen, und frage mich, was den Drachen zugestoßen sein könnte.\n\nBitte dringt in den Tempel vor und versucht, so viel wie möglich herauszufinden.", sourceObjective = "Findet mehr darüber hinaus, was im Tempel von Atal'Hakkar vor sich geht.", progress = "Welche Neuigkeiten bringt Ihr mir über Eranikus?", completion = "Was Ihr beschreibt, ist geradezu entsetzlich. Es ist deutlich schlimmer, als ich befürchtet hatte. Ich kann nur hoffen, dass einige der Drachen dort noch leben und sich versammeln lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82020] = { id = 82020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt nach Moonglade zurück", description = "Kehrt zu Loganaar zurück und sagt ihm, was wir herausgefunden haben. Ich werde selbst versuchen, den Tempel auszukundschaften, um hoffentlich Kontakt zu den Drachen herzustellen oder wenigstens weitere Erkenntnisse zu gewinnen.", sourceObjective = "Kehrt zu Loganaar in Moonglade zurück.", completion = "<Loganaar seufzt tief.>\n\nNoch mehr schlechte Nachrichten. Gut, ich danke Euch, dass Ihr Euer Leben auf Spiel gesetzt habt, um diese Erkenntnisse aus dem Tempel zu beschaffen und sie mir zu überbringen. Ich muss die anderen Druiden informieren, damit wir unsere nächsten Schritte planen können.\n\nDanke erst einmal. Vielleicht wende ich mich bald erneut an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[82021] = { id = 82021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zufällige Wende der Ereignisse", description = "Na, guten Tag, {name}! Ich habe hier nur gestanden und die Landschaft genossen und konnte nicht umhin, Euer Dilemma mitanzuhören. Zufälligerweise kann ich wohl genau das besorgen, was Ihr zur Bekämpfung Eures \"Alptraumproblemchens\" braucht.", sourceObjective = "Hört Euch an, was die schattenhafte Gestalt zu sagen hat.", progress = "Ich muss schon sagen, das hätte nicht besser funktionieren können, wenn ich es geplant hätte. Das Schicksal ist Euch wohlgesonnen.\n\n<Ihr habt den Eindruck, dass die schattenhafte Gestalt vor Euch schmunzelt.>", completion = "Ist es nicht ermutigend, jemanden wie mich zu haben, mit immer genau dem parat, was Ihr braucht? Und genau, wann Ihr es braucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[82022] = { id = 82022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlechte Nachricht...", description = "Die gute Nachricht ist: Es gibt eine Lösung. Die schlechte ist, dass die Beschaffung der Dinge, die erforderlich sind, um den Schrecken zu überleben, ein wenig aufwendig sein wird. Ich weiß, dass es heutzutage schwierig ist, gute Hilfe zu bekommen. Wenn dieser Abenteuer damals einfach nur das getan hätte, worum ich ihn gebeten hatte, würdet Ihr jetzt vor einer heißen Mahlzeit und einem kalten Bier in einem Gasthaus sitzen und müsstet Euch nicht mit dieser Sache herumplagen.", sourceObjective = "Findet den von der schattenhaften Gestalt beschriebenen Abenteuer und beschafft die leerenaufgeladenen Unterarmschienen.", progress = "Wie läuft die Suche?", completion = "Ah, die haben anscheinend keinen Saft mehr. Schade, aber das lässt sich leicht beheben. Um sie aufzuladen, müsst Ihr eine dichte Konzentration an Nagazauberern finden und sie massenhaft abschlachten. Manchmal haben sie etwas dabei, das sich \"Leerenkern\" nennt, also filzt die Leichen, bringt mir so ein Ding und... Ha! War nur ein Witz! Wenn Ihr Euch jetzt sehen könntet...\n\nGebt mir einen Augenblick, dann sollte ich etwas Energie reinleiten können... und bitte! Jetzt seid Ihr bereit, einen Alptraum zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[82023] = { id = 82023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Unterarmschienen", description = "Wisst Ihr, ich bin ein einigermaßen anerkannter Ritter und habe mir vor Kurzem die Befreiung des Landes von einem besonders schrecklichen Bösen auferlegt, das sich auf einer östlich von uns gelegenen Insel niedergelassen hatte. Als ich die widerliche Kreatur fand, folgte darauf ein wahrhaft epischer Kampf, der stundenlang andauerte, bis ich die Bestie endlich in die Flucht schlagen konnte, wonach sie zweifelsohne ihren Wunden erlag. Ich habe es gerade noch zurück geschafft und brach dann vor Erschöpfung zusammen. Während des Kampfes muss ich meine Unterarmschienen verloren haben.", sourceObjective = "Findet den Bau \"Bestie\", die der verletzte Gnom beschriebenen hat, und beschafft die leerenaufgeladenen Unterarmschienen.", progress = "<Der junge Murloc schaut Euch an und gibt ein süßes Gurgeln von sich.>\n\nEuch fällt ein Häuflein Erde neben dem Murloc auf. Vielleicht solltet Ihr darin nach den Unterarmschienen schauen?", completion = "Ihr habt einen kleinen Bau gefunden, der einem entzückenden und offenbar sehr freundlichen kleinen Murloc gehört. Das kann doch unmöglich die von dem Gnom beschriebene Bestie sein?\n\n<Der winzige Murloc gibt ein leises Gurgeln von sich und erbricht ein Paar schleimbedeckte Unterarmschienen vor Eure Füße.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82043] = { id = 82043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Götter", description = "Irgendwas stimmt mit dem Loa vom Hyjal nich'. Die mächtigsten Naturgeister wach'n schon seit Tausenden von Jahr'n über diesen Berg, doch sie verschwinden langsam einer nach 'm andren.\n\nAgamaggan, der größte der uralten Loa, ist schon vor langer Zeit gestorb'n. Aber die Amanitrolle haben Wege, mit den Toten zu sprech'n! Findet das Voodoo, das sie nutz'n, und bringt es dann zu den Razorfen. Sprecht mit Agamaggan und fragt ihn, was mit seinesgleichen passiert ist.", sourceObjective = "Sammelt ein Wildgeflüstergebräu aus Jintha'Alor im Hinterland und verwendet es auf dem Gipfel der Hügel von Razorfen, um mit dem Geist von Agamaggan zu sprechen.", completion = "Selbst jenseits des Schleiers des Todes spüre ich diesen Schatten, der sich auf den Hyjal und meine Sippe legt.\n\nNehmt dies, Sterblicher. Ihr werdet es brauchen für das, was bald kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82044] = { id = 82044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Götter", description = "Eine Finsternis hat im Smaragdgrünen Traum Fuß gefasst und die uralten Geister des Hyjal mit Verwirrung und Furcht belegt.\n\nFindet diese wahnbesessenen Geister, <Sterblicher/Sterbliche>, und lockt sie mit meinem Gebrüll in den Kampf.\n\nWenn Ihr ihre verderbten Gestalten vernichtet, werden Ihre Geister geläutert und sie werden neu geboren.", sourceObjective = "Bringt wilde Opfergaben zur Abgesandten des Schattenzahns im Teufelswald. Setzt Agamaggans Gebrüll bei einem wahnbesessenen Uralten ein und besiegt ihn, um Euch wilde Opfergaben zu verdienen.", progress = "Ich spür 'ne Veränderung am Berg, {name}. Was bringt Ihr mir?", completion = "Ihr habt den Loa 'nen groß'n Dienst erweis'n, {name}. Ich werd die Opfergab'n einsetz'n, um sie zurück zum Hyjal zu führ'n.\n\nBringt mir mehr Opfergab'n, dann werd ich Euch vielleicht 'nen Teil von unsrem Klanschatz zukommen lass'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[82055] = { id = 82055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dünenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Dünenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Dünenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Dünenkarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Dünenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82056] = { id = 82056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraumkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Alptraumkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Alptraumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[82057] = { id = 82057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Seuchenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Seuchenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Seuchenkarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Seuchenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82058] = { id = 82058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildniskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Wildniskartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", sourceObjective = "Gebt das Wildniskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Wildniskarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Wildniskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82062] = { id = 82062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr denn je", description = "Wir mussten sicherstellen, dass wir Euch vertrauen können. Solche Freunde sind rar gesät.\n\nEin Übel wächst heran, eine dritte Fraktion innerhalb von Azeroth. Sowohl die Horde als auch die Allianz arbeiten ahnungslos auf ihr eigenes Ende hin. Wir haben lediglich die Ressourcen, um ihr Vorrücken zu verlangsamen und Informationsverbünde zu bilden.\n\nNehmt dies, bringt Eure Lebensgeister in Schwung und blickt auf bessere Tage zurück. Bald kommt die Zeit, in der wir unsere verstärkten Reihen zur Abschreckung präsentieren müssen.", sourceObjective = "<Euch wird ein kleines Paket überreicht, auf dem ein ordentlich gefaltetes Hemd liegt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82068] = { id = 82068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraumeinfälle abwehren", description = "Schließt noch heute einen Alptraumeinfall im Hinterland oder in Feralas ab, um eine zusätzliche Belohnung zu erhalten.", sourceObjective = "Schließt noch heute einen Alptraumeinfall im Hinterland oder in Feralas ab und meldet Euch bei Feldhauptmann Korlian oder Feldhauptmann Arunnel.", completion = "Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[82071] = { id = 82071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigendes Feuer", description = "In die verkohlten Notizen ist irgendetwas eingewickelt. Eine Art Sapta. Ihr könnt Euch nicht daran erinnern, dass es so ausgesehen oder gerochen hat, doch ansonsten wirkt es authentisch. Irgendetwas stimmt aber nicht. Könnte es von einer anderen Magie besudelt worden sein. In der Nähe muss sich ein Geisterfelsen befinden, obwohl Ihr Euch an keinen erinnern könnt. Wenn Ihr ihn findet, könnt Ihr vielleicht ergründen, was hier so seltsam ist.", sourceObjective = "Findet den besudelten Geisterfelsen und trinkt das düstere Feuersapta.", completion = "Ihr seid stark. Ihr läutert das Feuer. Ihr haltet die Verderbnis auf.\n\n\nIhr findet die Verderbnis und haltet sie auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[82072] = { id = 82072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuternde Erde", description = "Eine vertraut aussehende Flasche Sapta wurde in verschmierte Zettel eingewickelt und liegt vor Euch. Das Zeug wirkt seltsam düster, doch seine Magie kommt Euch größtenteils bekannt vor. Der Hauch eines fremdartigen Zaubers verdirbt die Mixtur. Euer Instinkt sagt Euch, dass es in der Nähe einen Geisterfelsen geben muss, doch Ihr könnt Euch an keinen erinnern. Wenn Ihr ihn findet, könnt Ihr diesem Mysterium vielleicht auf den Grund gehen.", sourceObjective = "Findet den besudelten Geisterfelsen und trinkt das düstere Erdsapta.", completion = "Das Leben gedeiht wieder. Stärke ist erforderlich.\n\n\nVerderbnis ist woanders. Findet sie und haltet sie auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[82073] = { id = 82073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberndes Wasser", description = "Ausgeblichene und durchweichte Zettel wurden um eine Flasche mit trübem Inhalt gewickelt. Ihr könnt Euch nicht daran erinnern, dass sie jemals so ausgesehen haben könnte, aber doch recht ähnlich. Der Geruch ist allerdings komisch, als wäre er besudelt. In der Nähe muss sich ein Geisterfelsen befinden, der aber wahrscheinlich schon lange aufgegeben wurde. Wenn Ihr ihn findet, habt Ihr vielleicht das fehlende Teil zu diesem seltsamen Puzzle.", sourceObjective = "Findet den besudelten Geisterfelsen und trinkt das düstere Wassersapta.", completion = "Ihr habt geläutert. Ihr habt wiederhergestellt. Ihr habt einen starken Geist. Ihr helft.\n\n\nDie Verderbnis lebt noch. Haltet sie auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[82074] = { id = 82074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antwort auf den Ruf des Feuers", description = "Ihr seid stark. Stark genug.\n\n<Der Elementar funkelt und flackert.>\n\nElemente von Feralas. Essenz. Findet den Schrein.\n\nNehmt ein Fragment. Das wird helfen.", sourceObjective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Feuerfragment, um den verderbten Schrein dort aufzudecken.", progress = "Das wird den Schrein läutern.", completion = "Hilfe ist nötig. Andere Elemente sind stark. Bringt sie her.", sourceObjectiveStatus = "unverified-source-field" }
quests[82075] = { id = 82075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antwort auf den Ruf der Erde", description = "Das Leben gedeiht nun. Wir brauchen mehr. Die Verderbnis muss aufgehalten werden.\n\n<Als sich der Elementar bewegt, schaben die Felsen aneinander.>\n\nFeralas. Elementare. Essenz und Schrein.\n\nFindet den Schrein. Nutzt das Fragment und findet ihn. Helft dabei, das Leben gedeihen zu lassen.", sourceObjective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Erdfragment, um den verderbten Schrein dort aufzudecken.", progress = "Das Leben gedeiht hier nun.", completion = "Das Leben gedeiht hier nun. Wir brauchen mehr. Andere Elemente. Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[82076] = { id = 82076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antwort auf den Ruf des Wassers", description = "Starker Geist. Ihr helft, die Verderbnis aufzuhalten.\n\n<Wasser wirbelt brausend um den Elementar.>\n\nGeschwister. Elementare von Feralas helfen. Die Essenz wird den Schrein finden.\n\nAuch das Fragment wird helfen. Läutert die Verderbnis.", sourceObjective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Wasserfragment, um den verderbten Schrein dort aufzudecken.", progress = "Werde Schrein säubern.", completion = "Säubere Schrein jetzt. Nicht stark genug. Brauche andere. Andere Elemente.", sourceObjectiveStatus = "unverified-source-field" }
quests[82081] = { id = 82081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zerbrochenes Ritual", description = "Dieses makellose Schulterblatt ist eindeutig identifizierbar: Hakkar ist in die körperliche Welt beschworen und bezwungen worden. Die Trolle auf der Insel Yoyomba werden mehr darüber erfahren wollen, was im Inneren des Versunkenen Tempels geschehen ist.", sourceObjective = "Bringt das Schulterblatt des gefallenen Avatars zu Molthor auf der Insel Yojamba.", progress = "{name}, welche Neuigkeiten bringt Ihr aus dem Tempel von Atal'Hakkar?", completion = "Das kann nich' sein... Die Gerüchte über den Tempel von Atal'Hakkar sind wahr?\n\nEuer Sieg im Inneren des Versunkenen Tempels wird lange im Gedächtnis der Zandalari verbleib'n. Dieser Knochen... 'ne seltsame Entscheidung, uns das zu überbring'n... Aber ohne Zweifel wurde einer gebraucht, um Hakkar in die körperliche Welt zu beschwör'n. Er wird hier in guten Händen sein, {name}. Dank Eurer Anstrengungen müss'n wir uns nich' länger Sorgen mach'n, ob Hakkar zurückkehrt... Richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[82083] = { id = 82083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zerbrochenes Ritual", description = "Dieses makellose Schulterblatt ist eindeutig identifizierbar: Hakkar ist in die körperliche Welt beschworen und bezwungen worden. Die Trolle auf der Insel Yoyomba werden mehr darüber erfahren wollen, was im Inneren des Versunkenen Tempels geschehen ist.", sourceObjective = "Bringt das Schulterblatt des gefallenen Avatars zu Molthor auf der Insel Yojamba.", progress = "{name}, welche Neuigkeiten bringt Ihr aus dem Tempel von Atal'Hakkar?", completion = "Das kann nich' sein... Die Gerüchte über den Tempel von Atal'Hakkar sind wahr?\n\nEuer Sieg im Inneren des Versunkenen Tempels wird lange im Gedächtnis der Zandalari verbleib'n. Dieser Knochen... 'ne seltsame Entscheidung, uns das zu überbring'n... Aber ohne Zweifel wurde einer gebraucht, um Hakkar in die körperliche Welt zu beschwör'n. Er wird hier in guten Händen sein, {name}. Dank Eurer Anstrengungen müss'n wir uns nich' länger Sorgen mach'n, ob Hakkar zurückkehrt... Richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[82084] = { id = 82084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Schriftkundigkeit", progress = "Euer Fortschritt in den arkanen Künsten ist wirklich vorbildlich, {name}. Ich denke, Ihr seid nun so weit, ein eigenes Zauberbuch zu verfassen.\n\nLasst mich überlegen... Ein Federkiel von den Eulenbestien des Hinterlands und eine Tinte aus Silithidenarz... Ja, das dürfte funktionieren. Und als Schreibpapier, das feinste Papyrus der Farraki.", completion = "Euer Zauberbuch ist fertig, {name}. Möget Ihr seine Seiten mit arkanen Geheimnissen füllen, die es mit jenen in den uralten Bibliotheken von Elun'dris und Zuldazar aufnehmen können." }
quests[82086] = { id = 82086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Schriftkundigkeit" }
quests[82089] = { id = 82089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Transmutation ist eine einzigartige Fähigkeit, die alle talentierten Alchemisten beherrschen, aber nur jene, die sich der Kunst voll und ganz ergeben, werden zu wahren Meistern darin. Ihr mögt das Zeug dazu haben, aber Ihr müsst mir beweisen, dass es Euch wirklich ernst damit ist, den Weg zu größerem Wissen und Begreifen zu beschreiten.\n\nBringt mir drei Arkanitbarren als Zeichen Eurer Hingabe an diese Kunst.", sourceObjective = "Bringt Crimeon Lablade drei Arkanitbarren.", progress = "Drei läppische Arkanitbarren sind doch sicherlich nichts im Austausch gegen dieses Wissen?", completion = "Sehr gut, ich erkenne Eure Hingabe.\n\n<Crimeon stopft sich die Barren hastig in seinen Rucksack>\n\nJa? Oh, Transmutation. Natürlich. Rührt Euch nicht, hierfür werde ich meine ganze Konzentration benötigen.\n\n<Crimeon wedelt dramatisch mit seinen Händen und ein winziger Funke schießt aus seinem rechten Zeigefinger>\n\nNun, äh, ja. Das sollte reichen. Vermutlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[82090] = { id = 82090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mix aus Spaß und Profit", description = "Jeder Alchemist, der etwas taugt, wird Euch erzählen, dass es in der Kunst immer darum geht, die Gewinnspanne zu maximieren. Es geht immer darum, die Materialien günstig zu erwerben, in großen Mengen zu produzieren und dann zum bestmöglichen Preis zu verkaufen. Was, wenn ich Euch erzählen würde, dass es einen Weg gibt, Materialien sehr, sehr weit zu strecken? Nun, als selbsternannter \"Meister der Mixologie\" habe ich genau das, was Ihr benötigt, um Euch auf ein ganz neues Niveau in Sachen Elixiere und Tränke zu bringen. Bringt mir 10 Unsichtbarkeitstränke, 10 Elixiere des Dämonentötens und 5 Elixiere der Weisen, dann zeige ich Euch, wie der Hase läuft.", sourceObjective = "Bringt Mischmeister Blix 10 Unsichtbarkeitstränke, 10 Elixiere des Dämonentötens und 5 Elixiere der Weisen.", progress = "Hört mal, ich habe jede Menge potenzielle Schüler, die nur darauf warten, etwas von mir zu lernen. Habt Ihr, worum ich Euch gebeten habe? Wenn nicht, dann zieht Leine.", completion = "Oh, wow, Ihr habt die Sachen wirklich dabei? Nun gut. Dann wollen wir mal Wasser aufsetzen und Euch zu einem richtigen Mixologen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82093] = { id = 82093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dschungeldurian", progress = "Diese kräftig und penetrant riechende Frucht wird Euch helf'n, bei bester Laune zu bleib'n, während Ihr die Sümpfe des Elends durchquert und den Tempel von Atal'Hakkar erkundet. Lasst Euch von dem Geruch nicht in die Irre führ'n, mein Volk schätzt diese Frucht sehr!\n\nWenn Ihr mir was Schönes von Euren Abenteuern mitbringt, werde ich Euch dafür belohn'. Ein paar unsrer besten Durianfrüchte sollt Ihr für Eure Anstrengungen bekomm'! Hand drauf?", completion = "Taz'dingo! Genießt die leck're, süße Durian, aber denkt immer dran... Keine Erstattungen!" }
quests[82094] = { id = 82094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des verlorenen Tempels", progress = "Dem allerstärkst'n Abenteurer biete ich die allerbest'n Angebote. Ich hab da was, was Eure Schultergegenstände verbessert: die Macht der Atal'ai selbst! {name}, wenn Ihr Mojo von den Allerstärkst'n der Atal'ai im Tempel gefund'n habt, dann geb ich Euch was dafür.\n\nEs muss dabei keine vorschnelle Entscheidung getroff'n werd'n, meine Angebote sind einfach die best'n...", completion = "Zieht ruhig weiter. Wenn Ihr noch was braucht, dann wisst Ihr, wo Ihr mich findet, {name}!" }
quests[82095] = { id = 82095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gott Hakkar", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nSeid gewarnt: Sogar im Entstehen wird er schon über unfassbare Macht verfügen und er wird sich Euch mit der ganzen Kraft seiner Wut widersetzen.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", sourceObjective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", progress = "Habt Ihr den Avatar von Hakkar besiegt, {name}? Hat seine Essenz das Ei, das ich Euch gab, schon ermächtigt?", completion = "Die Essenz von Hakkar wurde eingefangen! Gerade jetzt beginnt sich das Leben im Ei zu regen! Sind die Geschichten von Hakkar doch wahr?\n\nDas darf nicht wahr sein! Ich fürchte mich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Ich werde dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät.\n\nEure Dienste für mich haben nun ein Ende, {name}. Ihr habt eine Legende berührt, und Eure Taten werden eines Tages das Antlitz unserer Erde verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[82096] = { id = 82096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Balkonen, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand. Es war eine Art Altar... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", sourceObjective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", progress = "Während Ihr die Statue untersucht, bemerkt Ihr eine Vertiefung an ihrer Seite, die genau die Größe des Zeichens hat, das Marvon Euch mitgab...", completion = "Ihr legt den Steinreif in die Öffnung und hört, wie er an seinem Platz einrastet.\n\nNun, da der Stein an seinem Platz ist, könnt Ihr weitermachen... aber was solltet Ihr als Nächstes tun?\n\nVielleicht solltet Ihr diesen Altar etwas näher untersuchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[82097] = { id = 82097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Kreises", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, {name}. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", sourceObjective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich im Kreis der Statuen verbirgt.", completion = "Das Auge des Götzen glitzert an der Spitze des Trümmerhaufens. Seine Transparenz enthüllt etwas Glänzendes, das sich dahinter versteckt. Ihr bewegt einige größere Brocken Geröll zur Seite und befreit, was sich darunter befindet.\n\nDer Schatz der Atal'ai ist nun Euer.", sourceObjectiveStatus = "unverified-source-field" }
quests[82098] = { id = 82098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tempel von Atal'Hakkar", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, {name}.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde <einen Helden/eine Heldin> zurück. Wir werden uns den Ruhm teilen.", sourceObjective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Fassbauch in Stormwind.", progress = "Da sich langsam das Dunkel über meine Laufbahn senkt, wende ich mich an Euch, {name}, damit Ihr mir bei meinem letzten Auftrag für die Forscherliga helft. Wenn meine alten Knochen genug Kraft aufbringen würden, die Sümpfe des Elends und den Versunkenen Tempel zu meistern, würde ich direkt an Eurer Seite kämpfen.\n\nMein Stolz macht es mir schwer, Euch um Eure Hilfe beim Sammeln der Schrifttafeln der Atal'ai zu bitten. Doch das hohe Alter schließt andere Möglichkeiten aus.\n\nBitte helft mir, {name}. Ich möchte erst aus der Forscherliga ausscheiden, wenn ich ihre letzte Bitte erfüllt habe.", completion = "Die Schrifttafeln der Atal'ai! Ich danke Euch, {name}!\n\nWenn ich sie der Forscherliga übergeben habe, werden unser beider Namen in die Geschichte eingehen. Ihr habt einem alten Zwerg geholfen, die letzte Verpflichtung seines Lebens zu erfüllen. Dafür bin ich Euch ewig dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[82099] = { id = 82099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunst des Bösen", description = "Um ehrlich zu sein, {name}, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt: Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tiefenlauerern, Düsterwürmern oder Schlammen, die man dort findet. Viel Glück, {name}!", sourceObjective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro.", progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, {name}! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[82100] = { id = 82100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Atal'Hakkar", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursacht hat, müssen wir die Mächte verstehen, die ihnen innewohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", sourceObjective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard.", progress = "Wenn die Fetische der Atal'ai die Macht besitzen, Hakkar zu beschwören und Jammal'ans Prophezeiung zu erfüllen, müssen wir sie haben. Die Horde muss solche Mächte verstehen!", completion = "Tapferer {class}, Ihr habt Euch heldenhaft für die Horde eingesetzt.\n\nWir müssen uns unverzüglich um diese vielen Fetische von Hakkar kümmern!", sourceObjectiveStatus = "unverified-source-field" }
quests[82101] = { id = 82101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff für die Unkrautvernichtung", description = "Ihr habt Glück, {name}! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet. Eines davon ist ein Unkrautvernichter auf kurze Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Vernichter benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tiefenlauerern, Düsterwürmern oder Schlammen.", sourceObjective = "Bringt den ungeladenen Unkrautvernichter und 5 Proben Dunst der Atal'ai zu Larion in Marschalls Zuflucht.", progress = "Das kann einen echt fertigmachen, {name}. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82102] = { id = 82102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Eranikus", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz erfülle, fühle ich, wie mein Halt im Traum sich zum Chaos bewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", sourceObjective = "Legt die Essenz des Eranikus in den Essenzborn, der sich in seinem Unterschlupf im Versunkenen Tempel befindet.", progress = "Während Ihr Euch dem Essenzborn nähert, von dem Eranikus Euch berichtet hat, ertönt seine Stimme erneut in Eurem Kopf.\n\n\"Ja, sterbliches Wesen, dieser Essenzborn wird den reinen Teil meiner Psyche, der sich noch in diesem Edelstein befindet, erlösen. Legt den Edelstein in den Born hinein und lasst die Magie des grünen Drachenschwarms Verderbnis und Besudelung von meinem Wesen entfernen. Erst dann werde ich wahre Erlösung finden und erst dann wird der Drachenschwarm in der Lage sein, seine Führung über die Atal'ai wieder zu bestätigen.\"", completion = "Ihr legt den Edelstein in den Essenzborn hinein.\n\n\"Ich danke Euch, sterbliches Wesen, Ihr habt... nein... das, das darf nicht sein! Nein! Die Verderbnis dieses verfluchten Gottes hat sogar die Reinheit eines Essenzborns des grünen Drachenschwarms beschmutzt! Bitte, nein, ich fühle, wie meine Essenz von mir gerissen wird! DIESER SCHMERZ! Ich fühle, wie mich die Umklammerung eines ewigen Alptraums umschlingt...\"\n\n\"Sterbliches Wesen, ich flehe Euch an! Findet jemanden vom grünen Drachenschwarm, um dem ein Ende zu bereiten... Helft mir... Ich bin in der Dunkelheit gebunden... auf ewig in Schmerzen... bitte nicht... foltern...\"", sourceObjectiveStatus = "unverified-source-field" }
quests[82104] = { id = 82104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an der Prophet", description = "Meine Begleiter von den Witherbark mögen keine Fremden in ihrer Nähe ihrer Heimat.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie er es ausdrückt, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", sourceObjective = "Der Verbannte der Atal'ai im Hinterland möchte den Jammal'ans Kopf.", progress = "Sobald Jammal'an nicht mehr ist, habe ich die Chance, zu meinem Volk zurückzukehren.\n\nMit Jammal'an als ihrem spirituellen Anführer ist der Untergang der Atal'ai gewiss.", completion = "Jammal'ans blindes Vertrauen in falsche Visionen führte mein Volk in die ewige Verdammnis.\n\nIch danke Euch, {class}, dass Ihr meine Verbannung gerächt habt. Ich trauere um mein Volk. Jetzt habe ich keine Heimat mehr, in die ich zurückkehren könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82106] = { id = 82106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschaffung des Steins der Macht", description = "Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, {name}. Nur die Trolle des Versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.\n\nIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... Sie sind nicht frei von Bösem.", sourceObjective = "Bringt die Voodoofedern zu Ashlam Valorfist.", progress = "Habt Ihr die elenden Trolle getötet?", completion = "Das ist ausgezeichnet, {name}. Ich könnte sagen, dass ich überrascht bin, allerdings habe nicht daran gezweifelt, dass Ihr uns nicht enttäuschen werdet.\n\nEs ist mir eine Ehre, Euch einen der heiligen Steine der Macht zu überreichen. Verwendet ihn überlegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82107] = { id = 82107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoofedern", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zum Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neue Gestalt verleihen können, damit ich Euch belohnen kann.", sourceObjective = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zum gefallenen Helden der Horde.", progress = "Seid Ihr schon zurück? Zeit ist für mich nicht mehr, was sie einst war. Vielleicht habt Ihr ja wirklich schon eine lange Reise hinter Euch...", completion = "Endlich kann ich die Kälte von Stahl wieder spüren, auch wenn es nur für einen Moment ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[82108] = { id = 82108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grüne Drache", description = "Ich entsende Euch nun auf eine gefährliche Jagd. Es gilt, den grünen Drachen Morphaz zu bezwingen und mir seinen Zahn zu bringen. Morphaz haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nWenn Ihr ihn besiegen möchtet, solltet Ihr nicht alleine gehen. Dieser Drache ist der Feind von vielen. Sucht nach anderen, die ihn ebenfalls zu vernichten suchen.\n\nDer Zahn des Drachen steht für die Macht, die ein Jäger in der Gesellschaft anderer findet. Bringt ihn zu mir, dann werdet Ihr viel gelernt haben.", sourceObjective = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb der Klippen nordöstlich der Ruinen von Eldarath.", progress = "Ich sehe Weisheit in Euren Augen, {name}. Ist Eure Jagd beendet?", completion = "Ihr habt die alten Wege erlernt, {name}, dafür belohne ich Euch mit einem Geschenk, das aus meinen Zeiten als {class} stammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82110] = { id = 82110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der azurblaue Schlüssel", description = "Es wird einige Zeit dauern, die Fragmente zu entschlüsseln und den Zauber zu bannen. Sobald ich mein Werk vollendet habe, werde ich die Tasche Lord Ravenholdt persönlich übergeben.\n\nAllerdings gibt es da noch das Problem mit dem Schlüssel, von dem gesagt wird, er befände sich im Besitz von Morphaz, einem grünen Drachen. Er haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nVersammelt Eure Getreuen und begebt Euch zu seinem Hort. Lord Ravenholdt erwartet Euch bei Eurer Rückkehr mit dem Schlüssel.", sourceObjective = "Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt.", progress = "Die Tasche ist von Erzmagier Xylem bereits angekommen. Habt Ihr den Schlüssel finden können?", completion = "Der Schlüssel! Und ich dachte schon, er sei für immer verloren. Bitte nehmt eines der verzauberten Gewänder aus meinem Lager. Die sind nur für Schurken von außergewöhnlichem Talent und enormer Loyalität bestimmt. Es sollte schon offenkundig sein, dass Ihr, {name}, nicht zu unterschätzen seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[82111] = { id = 82111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morphaz' Blut", description = "Jetzt zum letzten Teil, dem zweiten Heilmittel.\n\nDer grüne Drache Morphaz ist dafür bekannt, gegen alle Formen von Krankheit und Gift immun zu sein. Viele Druiden erlitten den Tod, um uns diese Nachricht zu übermitteln. Es gibt keinen Zweifel, dass sein Blut die für uns nötige Wirkung hat.\n\nEin Kurier des Zirkels des Cenarius wird die von Euch bereits beschafften Zutaten übernehmen, während Ihr nach der letzten sucht. Versammelt Eure Verbündeten und sucht den Unterschlupf des Drachen im Versunkenen Tempel von Atal'Hakkar auf. Bringt sein Blut anschließend zu Greta Mosshoof im Teufelswald.", sourceObjective = "Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt sein Blut zu Greta Mosshoof im Teufelswald. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends.", progress = "Habt Ihr das Blut von Morphaz?", completion = "Ihr habt Morphaz besiegt und uns sein Blut gebracht... Ich kann diese gute Nachricht kaum fassen!\n\nWir werden sofort mit der Verarbeitung der Zutaten beginnen und die Tiere und Bäume des Teufelswalds endlich heilen. Es wird sicherlich ein ganzes Leben lang dauern, das hier Geschehene rückgängig zu machen, aber dank Eurer Hilfe verfügen wir nun über die entsprechenden Mittel.", sourceObjectiveStatus = "unverified-source-field" }
quests[82112] = { id = 82112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Zutat", description = "Genau wie ich befürchtet hatte. Das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Lüftet dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Besorgt eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", progress = "Habt Ihr die Fäulnisranke?", completion = "Endlich werde ich ein wirksames Gift herstellen können. Ich will es Euch nicht erneut auferlegen, die Kreatur damit zu vergiften, da ich schon zu tief in Eurer Schuld stehe.\n\nSeid Euch meines Danks und meines Respekts gewiss. Mögen Eure Reisen immer gut verlaufen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82113] = { id = 82113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Voodoos", description = "Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.\n\nDie Trolle im Versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit Ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.", sourceObjective = "Bringt die Voodoofedern zu Bath'rah dem Windbehüter.", sourceObjectiveStatus = "unverified-source-field" }
quests[82114] = { id = 82114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morphaz vernichten", description = "Es gibt einen grünen Drachen, tief im Versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt.\n\nVor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren. Der Verlust eines Lehrlings ist mir zwar nicht unbekannt, allerdings trug dieser einen arkanen Splitter von unübertroffener Größe und Qualität.\n\nBitte versammelt Eure mächtigsten Verbündeten und dringt in die Tiefen des Tempels vor. Vernichtet Morphaz und entreißt ihm den arkanen Splitter aus seinem Magen.", sourceObjective = "Beschafft den arkanen Splitter von Morphaz und kehrt mit ihm zu Erzmagier Xylem zurück.", progress = "Habt Ihr meinen alten Feind besiegt?", completion = "Unglaublich. Der Splitter ist sogar noch mächtiger geworden. Er scheint über all die Jahre die Energie des Drachen absorbiert zu haben.\n\nEs gibt nichts mehr, worum ich Euch nun bitten könnte. Meine Fähigkeit, das Arkane zu wirken, ist mit der Rückkehr dieses Splitters komplett wiederhergestellt. Meine erste Kreation sei die Eure, {name}, und Ihr müsst lediglich wählen...", sourceObjectiveStatus = "unverified-source-field" }
quests[82115] = { id = 82115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn von Trollen", description = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.\n\nNur die Voodoofedern von den Trollen aus dem Versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.\n\nDies ist keine gewöhnliche Aufgabe, {name}, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe. Er wird es sowieso nicht mehr brauchen.", sourceObjective = "Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel.", progress = "Habt Ihr die Federn? Mein Begleiter braucht eine Füllung!", completion = "Wunderbar, jetzt ist mein Begleiter komplett!\n\n<Impsy stopft die Puppe schnell aus und umarmt sie auf dämonische Weise.>\n\nOh, was für einen merkwürdigen Nebeneffekt diese Voodoofedern doch haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[82135] = { id = 82135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Hoffnung", description = "<Aeonas sagt nichts, sondern reicht Euch nur die Kugel und wendet sich ab.>", sourceObjective = "Bringt die Echokugel der Mannoroc zu Katharina der Reinen in Stormwind.", progress = "Willkommen zurück, {name}. Was habt Ihr da...\n\nAu weh.", completion = "Diese Geschichte bereitet mir wahrlich Sorgen. Der {class} in mir kann sich unmöglich damit abfinden, dass er bereitwillig Umgang mit einem Mitglied der Geißel hatte... doch der menschliche Teil in mir versteht, wie stark die Bande der Freundschaft sein können.\n\nIch danke Euch, dass Ihr die Kugel hergebracht habt. Ich werde dafür sorgen, dass sie in dem tiefsten uns bekannten Verlies aufbewahrt wird.\n\nAch, und eins noch: Ich habe das hier reparieren lassen und wollte es eigentlich Aeonas bei seiner Rückkehr überreichen. Sicher würde er wollen, dass Ihr es an seiner Stelle führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82208] = { id = 82208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Freund der Bibliothek", sourceObjective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[82209] = { id = 82209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbeutelkopfgeld", progress = "Ihr seid ja schon wieder da, {name}! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt." }
quests[82210] = { id = 82210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld für Trollhalsketten", progress = "Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhämmern. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!\n\nIch benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, {name}.", completion = "Ein weiterer Satz Halsketten bedeutet, dass es weniger Trolle im Hinterland gibt, derentwegen man sich Sorgen machen muss! Ihr habt es wieder geschafft, {name}. Leistet weiter so gute Arbeit!" }
quests[82271] = { id = 82271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr leuchtendes Skorpidblut", progress = "Die Idee mit dem Skorpidblut hat funktioniert, {name}! Es ist unglaublich wie viel man mit einem bisschen Leuchten hier und etwas Glitzern da erreichen kann. In null Komma nichts wird so aus einem Haufen Schrott eine preisgekrönte Attraktion. Meine Kunden lieben das Zeug und wenn etwas wichtig ist im Leben, dann ist es Liebe... findet Ihr nicht auch!\n\nIhr wart mir eine große Hilfe, {name}! Mein Bedarf ist zwar vorerst gedeckt, doch wenn Ihr mehr leuchtendes Skorpidblut findet, bringt es mir und ich tausche es gegen einige Lose ein.", completion = "Danke nochmals, {name}. Hier sind Eure Lose!" }
quests[82272] = { id = 82272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtendes Skorpidblut" }
quests[82273] = { id = 82273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Fledermausaugen", progress = "{name}, die Attraktion, an der ich arbeite, wird das schaurigste Ereignis seit dem Sturm auf Gnomeregan werden! Dies verdanke ich hauptsächlich Euch und all dem Tand, den Ihr mir gebracht habt. Vielen, vielen Dank!\n\nIch brauche nicht viel mehr, aber... solltet Ihr mir noch mehr böse Fledermausaugen von Fledermäusen der Östlichen Pestländer bringen... dann könnte ich noch weitere Lose des Dunkelmond-Jahrmarkts für Euch haben.", completion = "Danke nochmals, {name}. Hier sind Eure Lose!" }
quests[82274] = { id = 82274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Fledermausaugen" }
