quests[82307] = { id = 82307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
