quests[82316] = { id = 82316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieben Augen suche ich...", progress = "Sieben verborgene Augen suche ich... Bringt sie zu mir, dann werdet auch Ihr sehen.", completion = "Ihr werdet gesehen..." }
quests[82323] = { id = 82323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbenprächtige Federbüsche" }
quests[82656] = { id = 82656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederweste", description = "Wildlederwesten sind die Grundlage jeglicher Wildlederrüstungssets. Die Struktur der Weste und das Wildrankengeflecht darin erzeugen ein Produkt, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Dies ist keine einfache Lektion, aber eine, für die Ihr sicherlich das nötige Geschick habt.", sourceObjective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe? Und vergesst bitte die Wildranke nicht!\n\nSelbst mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nWährend Ihr in den Lektionen voranschreitet, werden die Fertigkeiten, die ich Euch beibringe, zu einer wahren Kunst werden.", completion = "Das hier sind ein paar sehr schöne Stücke, {name}. Die Handwerkskunst und Sorgfalt, die in die Herstellung dieser Dinge geflossen sind, zeigen, dass Ihr beschlossen habt, Euch völlig diesen Aufgaben zu widmen.\n\nIhr habt meine Forderungen erfüllt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", sourceObjectiveStatus = "unverified-source-field" }
quests[82657] = { id = 82657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederweste", description = "Wildlederwesten sind die Grundlage aller Wildlederrüstungssets. Das Gerüst der Weste verbindet sich mit der Wildranke, um ein Produkt zu erzeugen, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Das ist ein großer Auftrag, aber sicher keiner, bei dessen Erfüllung Ihr Schwierigkeiten haben werdet.", sourceObjective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe, die ich bestellt habe? Und vergesst bitte die Wildranke nicht!\n\nSchon mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nUnd die Handschuhe... tja, die sind nur für meinen eigenen Bedarf. Vergesst nicht, Ihr arbeitet für mich!", completion = "Das hier sind ein paar sehr schöne Stücke, {name}. Durch die Handwerkskunst und Sorgfalt, die in ihre Fertigung gesteckt wurden, werden sie einige Silbermünzen mehr einbringen als ein durchschnittlich gefertigtes Stück.\n\nIhr habt meinen Auftrag erledigt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", sourceObjectiveStatus = "unverified-source-field" }
quests[82662] = { id = 82662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Als <Waffenschmied/Waffenschmiedin> werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, {name}, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei einbringen könnt. Ich meine, zeigt mir, dass Ihr es draufhabt, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!", sourceObjective = "Um <Waffenschmied/Waffenschmiedin> zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82665] = { id = 82665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Waffenschmieds...", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, {name}. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein, <ein Waffenschmied/eine Waffenschmiedin>. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\nAlles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.", sourceObjective = "Um <Waffenschmied/Waffenschmiedin> zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82850] = { id = 82850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischöl", progress = "Fischöl hält die Räder des Krieges am Laufen! Wenn Ihr welches für mich habt, werde ich Euch dafür reichlich entlohnen.", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[82851] = { id = 82851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verordnung der Dunkeleisenzwerge", progress = "Wusstet Ihr, dass es bei den Dunkeleisenzwergen Tradition ist, dass der Senat Gesetzesvorschläge zu explosiven Geschossen verfasst? Und wenn die Gesetze dem Imperator nicht gefallen, nun, dann... BUMM!\n\nWas schaut Ihr mich so an? Vertraut Ihr Eurem alten Kumpel Grizzby etwa nicht?", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[82853] = { id = 82853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderturbolader", progress = "Schade, dass die Schifffahrtswege zurück nach Kezan mittlerweile so unzuverlässig sind. Zuhause bekommt man für ein paar Kupferstücke Turbolader im Überfluss. In den Maschinenläden fallen sie schon aus den Regalen. Die wissen nicht, wohin mit dem Zeug.\n\nWie auch immer, wenn Ihr ein paar Turbolader habt, mit denen Ihr nichts anzufangen wisst, nehme ich sie Euch nur zu gerne ab!", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[83188] = { id = 83188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überirdischer Schatz" }
