quests[83191] = { id = 83191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überirdischer Schatz", sourceObjective = "Bitteschön, Boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83192] = { id = 83192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überirdischer Schatz", sourceObjective = "Bitteschön, Boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[83808] = { id = 83808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Klemme", description = "Ihr habt mich fast zu Tode erschreckt! Ich habe Euch kommen gehört und war überzeugt, dass die Toten mich endlich aufgespürt hätten! Doch Ihr seid eine wahre Augenweide. Bitte, ich muss von diesem Ort verschwinden und meinen Herrn, Sir Dalton, finden. Würdet Ihr meine Waffe für mich holen? Sie wurde mir draußen auf dem Schlachtfeld entrissen und ich war gezwungen, in diese Scheune zu fliehen.", sourceObjective = "Findet das Schwert des Knappen Cuthbert auf dem Feld im Süden und bringt es ihm.", progress = "Habt Ihr das Schwert gefunden?", completion = "Danke, {class}. Ich kann Euch nicht genug für Eure Hilfe danken.\n\nIch brauche einen Moment, um mich zu sammeln. Ich habe einen üblen Hieb auf den Kopf eingesteckt und bin nicht sicher, wie gut ich schon kämpfen kann. Oh, das Licht helfe mir, ich hoffe, Sir Dalton ist in Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83822] = { id = 83822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefallene Ritter", description = "Ihr sagtet, Ihr habt seine... Leiche gefunden? Nein... mein Herr darf nicht tot sein. Unsere Aufgabe ist noch nicht erfüllt.\n\nIch... danke Euch, {class}. Ich habe mit dem Schock zu kämpfen, doch ich bin froh, dass Ihr ihn gefunden habt.\n\nWie es scheint, liegt seine Queste nun an mir. Doch zuerst muss ich zu seiner Leiche zurückkehren und sie verbrennen, damit er nicht Teil desselben Unheils wird, dass er vernichten wollte. Wenn ich noch eine Bitte an Euch richten dürfte, würdet Ihr mich an den Ort führen, wo Sir Dalton gefallen ist?", sourceObjective = "Führt den Knappen Cuthbert zur Leiche des gefallenen Ritters, den ihr zuvor gefunden habt, und helft ihm, sie zu verbrennen.\n\nWenn Ihr Cuthbert aus den Augen verliert, wird er sich zu seinem Versteck in der Scheune bei Dalsons Tränenfeld zurückziehen und dort auf Euch warten.", completion = "Ich stehe wohl erneut in Eurer Schuld, {class}. Sogar im Angesicht seiner Leiche ist es schwer zu glauben, dass es wahr ist. Ich stand in Sir Daltons Diensten, seit ich ein kleiner Junge war, aber ich habe das Gefühl, noch so viel lernen zu müssen, wenn ich beenden will, was Sir Dalton begonnen hat.\n\nIch kann Euch nicht länger aufhalten. Ihr habt mir bereits übermäßig viel Ehre mit Eurer zuvorkommenden Hilfe erwiesen. Bitte, lasst mich Euch nicht länger zur Last fallen. Ich werde hier rausfinden, irgendwie.", sourceObjectiveStatus = "unverified-source-field" }
quests[83823] = { id = 83823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Gewalt", description = "Eure Technik ist sehr interessant, {name}. Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu mir passt, glaube ich. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt!", progress = "Eure Technik ist sehr eindrucksvoll! Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu Euch passt. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt und kann es kaum erwarten, es gegen unseren Feind anzuwenden!", completion = "Euer Knappe hat seine Fähigkeiten im Verlauf des Abenteuers an Eurer Seite verbessert!" }
quests[83934] = { id = 83934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit dem Geld!", description = "Heda! Ihr sehr aus wie <ein \"findiger Abenteurer\"/eine \"findige Abenteurerin\">, vielleicht könnt Ihr mir helfen. Seht Ihr, meine Brüder und ich kamen von den Verlorenen Inseln auf der Suche nach einem neuen Geschäftsmodell, aber wir sind auf einige Piraten getroffen, die unser Startgeld gestohlen haben. Die Leute, die unsere Operation in der Heimat finanzieren, sind nicht gerade verständnisvoll, also würde es sich für Euch lohnen, wenn Ihr uns etwas des verlorenen Geldes zurückbringt. Es ist kein gewöhnliches Gold, aber Ihr werdet es erkennen, wenn Ihr es seht.", sourceObjective = "Bringt einen angelaufenen Real aus Undermine zu Pix Xizzix in Booty Bay.", progress = "Was habt Ihr für mich, {race}?", completion = "He! Das ist großartig!\n\nWenn Ihr mehr von unserem Geld findet, kommt zu mir. Wir haben eine große Auswahl an Waren, die wir gerne mit Euch tauschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83935] = { id = 83935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg frei machen", description = "Das Pochen in meinem Kopf hat etwas nachgelassen, aber ich glaube nicht, dass ich mich hier alleine rauskämpfen kann. Ich bitte Euch nur ungerne erneut, aber würdet Ihr mir helfen, die Reihen zu lichten und mir einen Fluchtweg freizuräumen?", sourceObjective = "Tötet 5 verseuchte Zombies, 10 Skelettschrecker und 10 faulende Kadaver, um den Weg für Knappen Cuthberts Flucht freizumachen.", completion = "Habt erneut Dank, {class}. Wenn wir jemanden wie Euch bei uns gehabt hätten, als wir überfallen wurden, bin ich sicher, dass wir das Blatt im Nu gegen unsere Angreifer gewendet hätten!\n\nIch habe jetzt etwas Rückenwind und muss Sir Dalton finden. Er ist ein fähiger Ritter, aber er braucht sicherlich meine Hilfe. Sagt, habt Ihr ihn da draußen gesehen? In seiner strahlend weißen Plattenrüstung ist er schwer zu übersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83936] = { id = 83936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daltons Queste", description = "<Knappe Cuthbert starrt leer auf die brennende Leiche von Dalton. Er steht sichtlich unter Schock. Ihr könnt sehen, dass er nicht in der Verfassung ist, die Queste fortzuführen, für die er mit seinem Herrn ausgezogen ist. Vielleicht solltet Ihr mit ihm sprechen, um zu sehen, wie Ihr ihm noch helfen könnt?>", sourceObjective = "Sprecht mit Knappe Cuthbert, um mehr über Sir Daltons Queste zu erfahren.", completion = "Ich... weiß nicht, was ich sagen soll. Trotz der tristen Umstände kann ich mein Glück kaum fassen, mich im Dienst eines anderen Helden der Allianz wiederzufinden. Ich kann nur hoffen, dass ich Euch besser dienen werde, als ich es für Sir Dalton tat.\n\nGeht voran, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[84008] = { id = 84008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Sachen Anmut", description = "Eure Technik ist sehr interessant, {name}. Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu mir passt, glaube ich. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt!", sourceObjective = "Euer Knappe hat seine Fähigkeiten im Verlauf des Abenteuers an Eurer Seite verbessert!", progress = "Dank Eurer Lehren fühle ich mich dem Licht näher als je zuvor. Ich beginne zu verstehen, dass die Rolle eines Paladins ist, ebenso die Gnade zu empfangen, wie das eigene Kampfgeschick zu verbessern. Ich werde diese Lektion verinnerlichen und das, was ich gelernt habe, anwenden, um unsere Verbündeten zu stärken!", completion = "Dank Eurer Lehren fühle ich mich dem Licht näher als je zuvor. Ich beginne zu verstehen, dass die Rolle eines Paladins ist, ebenso das Licht zu empfangen, wie das eigene Kampfgeschick zu verbessern. Ich werde diese Lektion gut verinnerlichen und anwenden, was ich gelernt habe, um unsere Verbündeten zu stärken!", sourceObjectiveStatus = "unverified-source-field" }
quests[84011] = { id = 84011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Sternenlotus", description = "Wir brauchen noch mehr Sternenlotus, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welche.", sourceObjective = "Sammelt 10 Sternenlotus in den Hinterland-Alptraumeinfällen und kehrt dann zu Feldhauptmann Korlian zurück.", progress = "Habt Ihr den Sternenlotus?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84012] = { id = 84012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Sternensilbererz", description = "Wir brauchen noch mehr Sternensilbererz, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welches.", sourceObjective = "Sammelt 10 Stücke Sternensilbererz in den Hinterland-Alptraumeinfällen und kehrt dann zu Feldhauptmann Korlian zurück.", progress = "Habt Ihr das Sternensilbererz?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84013] = { id = 84013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Sternenmuscheln", description = "Wir brauchen noch mehr Sternenmuscheln, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welche.", sourceObjective = "Sammelt 10 Sternenmuscheln in den Hinterland-Alptraumeinfällen und kehrt zu Feldhauptmann Korlian zurück.", progress = "Habt Ihr die Sternenmuscheln?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84014] = { id = 84014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Mondwurzel", description = "Wir brauchen noch mehr Mondwurzel, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", sourceObjective = "Sammelt 10 Mondwurzeln in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", progress = "Habt Ihr die Mondwurzel?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84015] = { id = 84015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr große Mondsteine", description = "Wir brauchen noch mehr große Mondsteine, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", sourceObjective = "Sammelt 10 große Mondsteine in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", progress = "Habt Ihr die großen Mondsteine?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84016] = { id = 84016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Monddrachenschuppen", description = "Wir brauchen noch mehr Monddrachenschuppen, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", sourceObjective = "Sammelt 10 Monddrachenschuppen in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", progress = "Habt Ihr die Monddrachenschuppen?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84017] = { id = 84017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu töten", description = "Ich habe das Gefühl, so viel in so kurzer Zeit gelernt zu haben. Ich glaube nicht, dass irgendjemand je bereit sein könnte, sich dem zu stellen, was vor mir liegt. Aber ich fühle mich so bereit wie nur möglich. Was sagt Ihr, {name}? Wollen wir gehen und diesen Kampf beenden?\n\nIch bin nicht sicher, wo wir anfangen sollten, aber ich schätze wir werden irgendwo in den Östlichen Pestländern Hinweise finden. Wir sollten vielleicht in Gebieten anfangen, wo sich der Kult der Verdammten versammelt.", sourceObjective = "Findet Arkonos und bereitet ihm ein Ende.", progress = "Vergeltung ist nah, ich kann es spüren!", completion = "Wie es scheint, haben wir unseren Gegner gefunden, aber wir können ihn nicht erreichen. Wir müssen einen Weg zu ihm finden, sodass wir zuschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[84124] = { id = 84124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis der Ehre", description = "Der spektrale Champion gibt auf und deutet auf den Altar.", sourceObjective = "Kehrt zum Altar der Ehrerbietung zurück", completion = "Auf dem von Euch geehrten Altar ruht eine majestätische, schwarz-goldene Zweihandaxt neben einem Folianten mit Legenden des Schlachtfelds.", sourceObjectiveStatus = "unverified-source-field" }
quests[84125] = { id = 84125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ziel so nah", description = "Diese niederträchtigen Nekromanten und ihre Tricks sind abstoßend. Wir müssen einen Weg finden, die Barriere zu Arkonos zu durchbrechen und ihm ein Ende zu machen!\n\nViele Zauberwirker des Kultes der Verdammten und der Geißel sind dafür bekannt, eine Vielfalt an Teufelsinstrumenten und Fokussen der dunklen Magie zu besitzen. Vielleicht haben einige der Schattenmagier oder Schreckenswirker in der Nähe etwas, womit wir den Schild durchdringen können?", sourceObjective = "Tötet Schattenmagier und Schreckenswirker im Giftigen Tal und durchsucht ihre Leichen nach etwas, mit dem Ihr den Schild durchdringen könnt, der Arkonos schützt.", progress = "Was habt Ihr gefunden, {name}?", completion = "Ja! Das könnte funktionieren. Gehen wir schnell zurück zum Schlachthaus und stellen dieses Gerät auf die Probe!", sourceObjectiveStatus = "unverified-source-field" }
quests[84126] = { id = 84126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kampf beenden", description = "So könnte es gehen, {name}. Dalton hat den Kult der Verdammten lange studiert und mir eine Reihe an Segen beigebracht, um ihre Magie abzuwehren. Dank Eurer Sorgfalt im Abschluss meiner Ausbildung glaube ich nun, dass ich stark genug bin, um einen dieser Segen auf das Gerät zu sprechen, der dessen Magie läutert, damit es die Barriere um Arkonos durchbrechen kann.\n\nKommt, brennen wir den Schild dieses Feiglings nieder und machen ihm endgültig den Garaus!", sourceObjective = "Tötet Arkonos den Verfluchten", progress = "Endlich Rache.", completion = "Kaum zu fassen, dass wir es geschafft haben. Ich kann Euch nicht genug für die Hilfe danken, die Ihr mir in dieser Sache habt zukommen lassen, {name}.\n\nDa es jetzt vollbracht ist... weiß ich nicht wirklich etwas mit mir anzufangen. Ich war so besessen von unserer Mission, dass ich überhaupt nicht darüber nachgedacht habe, was danach kommt. Für den Moment würde ich gerne unsere gemeinsamen Abenteuer fortführen, wenn Ihr es mir erlaubt. Ich habe viel gelernt, aber ich glaube, ich kann noch mehr von Euch lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84135] = { id = 84135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strandbot", description = "An der Küste, halb von der Nachmittagsgischt verschlungen, liegt eine seltsame Metallkonstruktion. Sie sieht ein wenig auch sie ein Mech, aber Ihr habt noch nie einen solchen gesehen. Euch fällt ein Schild an seiner Seite auf, auf dem steht: \"Eigentum von T.H.E.T.A: TiefseeHydraulik- und ErforschungsTechnik-Allianz\". Ihr entdeckt außerdem ein kleines Fach, das Ihr vielleicht öffnen könnt.", sourceObjective = "Nutzt einen Stein oder etwas Ähnliches, um Teile vom Mech zu lösen.", completion = "Mithilfe Eurer Waffen- und Feldfähigkeiten könnt Ihr das Fach aufbiegen und eine Phiole mit einer leuchtenden Flüssigkeit freilegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84136] = { id = 84136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tierherrschaftsmeisterin von Moonglade", description = "Während ich Van Amburgh aufspüre, könntet Ihr eine alte Bekannte von mir kontaktieren. Banteazo ist gerade in Moonglade, wo sie mit den Druiden das Verhalten der Tiere beobachtet, um die Begleiterausbildung zu optimieren. Sie hat außerdem bereits gegen Van Amburgh gekämpft und hat möglicherweise einige Hinweise. Grüßt sie von mir!\n\nWenn Ihr fertig seid, trefft mich in Winterspring, ich möchte dort einigen Spuren nachgehen. Ich habe ein altes Lager in den Hügeln im Norden, dort könnten wir uns unter vier Augen unterhalten.", sourceObjective = "Reist nach Nighthaven in Moonglade auf Kalimdor. Sucht nach Banteazo, einer Trolljägerin, und fragt sie nach ihren Erkenntnissen zur Tierherrschaft.", completion = "Ihr sagt, Estelenn lässt Grüße ausricht'n? Seltsam, ich hab diese Allianzflatter zuletzt geseh'n, als wir im Schlingendorntal Pfeile austauscht'n... Tja, dieser Ort is' neutraler Bod'n. Wenn sie Euch zu mir geschickt hat, dann wollt Ihr wohl über Tiere red'n, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[84137] = { id = 84137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanische Romanze", description = "Ihr fragt Euch, warum dieser Mech hier liegengeblieben ist und wofür diese Flüssigkeit sein könnte. Vielleicht könnt Ihr sie nutzen, um die nahe gelegenen Inseln und die Ölplattform zu erreichen, die mit dieser geheimnisvollen Organisation zusammenzuhängen scheinen. Wenn Ihr eines wisst, dann dass magische Tränke ziemlich gut schmecken.", sourceObjective = "Findet einen Nutzen für den gelenkten Auftriebsbeschleuniger.\n\nBereitgestellter Gegenstand:", completion = "Als Ihr die Ölplattform erreicht, entdeckt Ihr einen Mann in einem Laborkittel, der an einigen Robotern herumschraubt. Er bemerkt Euch und, immer noch mit der Steuerung beschäftigt, ruft: \"Fantastisch! Ihr kommt gerade rechtzeitig. Ich habe Euch erwartet. Ihr habt meinen wunderbaren Trank getrunken, stimmt's? Ich bin Dr. Jürgens und ich habe Euch einen Vorschlag zu machen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[84138] = { id = 84138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostige Gefallen", description = "Ich bin leitender Ingenieur, Gründer und Meistertechniker der TiefseeHydraulik- und ErforschungsTechnik-Allianz. Ich habe mein neuestes Experiment fast beendet und ich brauche Eure Hilfe! Ich arbeite an einem speziellen Gerät, das ressourcenreiche Dimensionen ortet. Um meine Konstruktion zu vollenden, brauche ich etwas: ein Buch mit arkanen Formeln, das ich einer alten Kollegin geliehen habe. Sie heißt Numi und arbeitet in Winterspring. Bringt mir das Buch, ich werde Euch großzügig belohnen!", sourceObjective = "Erklärt Numi in Winterspring die Situation um das Buch von Dr. Jürgens.", completion = "Sebastian braucht es? Er ist wirklich eine Nervensäge. Ihr verschwendet Eure Zeit mit der Frage nach dem Buch. Ich werde es Euch nicht geben oder Euch sagen, wo es ist. Aber vielleicht können wir einen Handel abschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84146] = { id = 84146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roter Taschenblues", description = "Was Ihr sucht, ist gut versteckt, und ich kann nur hoffen, dass das auch auf das zutrifft, was ich suche. Ich hatte eine rote Tasche mit einigen wertvollen, exotischen Dingen, die ich für optische Elektronik benutze. Aber ich habe sie bei einem Zeppelinunfall über der Brennenden Steppe verloren! Die Tasche könnte immer noch dort sein, aber bei den ganzen Orcs, Ogern und Plünderern musste ich meine Arbeit pausieren. Wenn Ihr die Tasche finden und mir wiederbringen könnt, werde ich Euch Jürgens' Buch überlassen.", sourceObjective = "Findet die rote Tasche, die Numi in Everlook bei einem Zeppelinabsturz über der Brennenden Steppe verloren hat.", completion = "Ihr findet die Tasche simpel und sorglos auf einem Tisch liegend vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[84147] = { id = 84147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[84148] = { id = 84148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[84149] = { id = 84149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Deliana in Ironforge.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, {name}?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", sourceObjectiveStatus = "unverified-source-field" }
