quests[84170] = { id = 84170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", sourceObjective = "Bringt Deliana in Ironforge einen Gürtel der Ehre und ein Paar Stulpen der Ehre.", progress = "Seid Ihr bereit, den Handel einzugehen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[84171] = { id = 84171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, {name}. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", sourceObjective = "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", sourceObjectiveStatus = "unverified-source-field" }
quests[84172] = { id = 84172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, {name}. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", sourceObjective = "Bringt Mokvar in Orgrimmar einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", sourceObjectiveStatus = "unverified-source-field" }
