quests[84177] = { id = 84177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angemessene Entlohnung", description = "Ihr habt große Verlässlichkeit bewiesen, {name}. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", sourceObjective = "Bringt Mokvar in Orgrimmar einen Gürtel der Furcht und ein Paar Wickeltücher der Furcht.", sourceObjectiveStatus = "unverified-source-field" }
