quests[84198] = { id = 84198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Euren Helm des Lichts und Eure Brustplatte des Lichts.", progress = "Seid Ihr bereit, mir unserer Abmachung entsprechend Eure Teile der Lichtrüstung im Austausch gegen den neuen Helm der Seelenschmiede und die neue Brustplatte der Seelenschmiede zu geben?", completion = "Ich werde Euch wahrlich vermissen, {name}. Ich stehe tief in Eurer Schuld, eine Schuld, die ich vermutlich niemals in der Lage sein werde zu begleichen.\n\nGenießt Eure neue Kopf- und Brustrüstung. Möge sie Euch für lange Zeit beschützen.", sourceObjectiveStatus = "unverified-source-field" }
