quests[84208] = { id = 84208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Mokvar Eure Helmkappe der Elemente und Eure Weste der Elemente.", progress = "Seid Ihr bereit, mir Eure Teile der Elementrüstung im Austausch gegen die neue Helmkappe der fünf Donner und die neue Weste der fünf Donner zu geben?", completion = "Ich werde Euch wahrlich vermissen, {name}. Ich stehe tief in Eurer Schuld, eine Schuld, die ich vermutlich niemals begleichen werden kann.\n\nGenießt Eure neue Kopf- und Brustrüstung. Möge sie Euch für lange Zeit beschützen und Euch dabei helfen, noch größere Ehren zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
