quests[84210] = { id = 84210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[84211] = { id = 84211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündererhöhle", description = "Als Ihr die Tasche aufhebt, fällt Euch sofort auf, dass sie so gut wie leer ist. Irgendwie habt Ihr das Gefühl, dass Numi das Buch nicht gegen eine leere Tasche eintauschen wird. Das Lager ist hingegen alles andere als leer. Verteidigt Euch und haltet die Augen nach weiteren ihrer Sachen offen.", sourceObjective = "Verteidigt Euch gegen Plünderer und bergt den Rest von Numis Materialien.", progress = "Habt Ihr die rote Tasche schon gefunden? Ich brauche das Zeug zurück, wenn ich mit den Teleskopaufrüstungen rechtzeitig zur Meteoritensaison fertig werden will!", completion = "Nun, Ihr habt Euch als ganz schön findig herausgestellt! Diese Materialien sind für mich unersetzlich. Ich kann Euch nicht genug danken! Hier, wie versprochen bekommt Ihr das Buch, das Jürgens zurückhaben möchte. Und nehmt noch ein heißes Getränk, bevor Ihr geht. Es ist kalt da draußen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84212] = { id = 84212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückbuchung", description = "Numi überreicht Euch Jürgens' Buch. Ihr verstaut es sicher und macht Euch auf den Rückweg auf die andere Seite der Welt.", sourceObjective = "Kehrt mit dem Buch, das Jürgens haben wollte, in das T.H.E.T.A-Labor zurück.", progress = "Hat sie das Buch behalten?", completion = "Wie ich sehe, habt Ihr mir mein gesuchtes Buch zurückgebracht. Ausgezeichnet! Euer Dienst ist von höchster wissenschaftlicher Bedeutung! Wir sind fast bereit, die geomantische Energie zu nutzen und ein stabiles Tor in eine andere Dimension zu öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84213] = { id = 84213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgerissen", description = "Schließt Euch mir in diesem historischen Experiment an und bezeugt die Wunder meiner Erfindung! Ich habe zwei Orte mit passenden geothermischen Bioflussenergien berechnet. Mit manuellen selbstzielenden Phasern kann ich uns direkt an die Koordinaten innerhalb kompatibler Regionen schicken.", sourceObjective = "Helft Dr. Jürgens beim Öffnen des Risses in Tirisfal oder Westfall.", completion = "Jürgens ist im Chaos verloren gegangen. Ihr seht eine schillernde Scheibe in einem länglichen Kristallbehälter. Darin befinden sich die zertrümmerten Überreste der inneren Mechanik des Golems. Ihr greift hinein, löst die Kabel vom Gehäuse und öffnet es.", sourceObjectiveStatus = "unverified-source-field" }
quests[84235] = { id = 84235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturzflug!", description = "Ihr sagt, Ihr sucht nach Van Amburgh? Wir könn' uns vielleicht geg'nseitig helf'n.\nDie Druiden hier mach'n sich Sorg'n weg'n einiger Fälle erhöhter elementarer Aktivität. Die Elementare umschwärmen 'n Fragment reiner elementarer Luft, das südlich des Sees einen Wirbelwind um sich herum manifestiert.\n\nGeht zu den Hügeln und holt Euch das elementare Fragment. Nehmt meinen Fledermausbegleiter, Zotl, um durch die Winde zu flieg'n, wenn Ihr keinen eigenen fliegend'n Begleiter habt. Zotl hängt in den Bäumen in der Nähe.", sourceObjective = "Reist in die Hügel im Süden von Moonglade auf Kalimdor. Sucht nach einem Luftstrudel östlich der Hügel in der Nähe des Holzschlundtunnels. Nutzt die Sturzflugfähigkeit eines Tierbegleiters, um den Wirbelsturm zu durchdringen, und bergt ein Fragment elementarer Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[84317] = { id = 84317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Mitternacht", description = "Der gewaltige Titan umhüllt Euch mit einer Ätherurora, und die Weisheit und die Erfahrungen der Jahrhunderte verbinden sich mit Euren Erinnerungen.", sourceObjective = "Erlangt astrale Einsichten", completion = "Magisch gebunden und schimmernd schwebt der Foliant vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[84318] = { id = 84318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ey!", description = "Ey! {class}! Ja, Ihr da! Ihr habt mir einen Gefallen getan, als ihr diesen deprimierenden Fleischanzug zerschlagen habt, in dem ich all die Jahre unterwegs war, aber ich fühle keinen großen Drang, weiterzuziehen. Das liegt sicher daran, dass ich noch ein paar \"Angelegenheiten\" zu klären habe, bevor ich mich auf den Weg machen kann. Tja, Dummkopf, Ihr wurdet soeben zur Hilfe verpflichtet!\n\nIhr müsst mir meinen Hammer bringen. Er sollte irgendwo bei Corrins Kreuzung sein und ist kaum zu übersehen. \n\nEy, nehmt das hier auch mit. Das ist mein Lieblingsgoldzahn. Reibt ihn, wenn Ihr meine Waffe gefunden habt.", sourceObjective = "Findet Orthas' fehlenden Hammer bei Corrins Kreuzung.", progress = "Was gibt's?", completion = "Ja, ich bin Euch sehr dankbar! Wo das jetzt geklärt ist, können wir den Rest zusammensetzen, damit ich mich auf den Weg machen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[84319] = { id = 84319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh nein, nichts da!", description = "Gute Arbeit mit dem Hammer, {class}. Als Nächstes ist meine Rüstung dran. Die brauche ich auf jeden Fall wieder, um ins Jenseits zu gelangen. \n\nDas einzige Problem ist, sie steckt in den Eingeweiden einer dieser Monstrositäten. Ich weiß, ich weiß, das ist viel verlangt, aber Ihr müsst verstehen, dass ich einst ein mächtiger Than unter dem Berg war. Ich kann einfach nicht weiterziehen, wenn ich weiß, dass sich diese Ahnenrüstung meines Klans in den Eingeweiden eines riesigen verrottenden Fleischbergs auflöst!", sourceObjective = "Orthas möchte, dass Ihr seine verschwundene Rüstung aus der Leiche einer Monstrosität irgendwo im Pestwald bergt.", progress = "Was gibt's?", completion = "Oh, sehr schön! Ein bisschen abgenutzt, aber das wird schon gehen. Wir haben noch eine letzte Sache zu erledigen. Ich brauche ein kleines Ritual. Nur etwas, das meinen verwirrten Geist wieder in Ordnung bringt, damit ich mich auf den Weg machen kann. Der letzte Teil ist vielleicht etwas unangenehm für Euch, weil Ihr ein {class} seid und so, aber glaubt mir, es muss sein! \n\nZumindest wird's nicht unappetitlicher, als meine Hosen in dieser Monstrositätensuppe zu suchen! Haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[84320] = { id = 84320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Erbstück", description = "Ich bin als Flüchtling nach Sturmwind gekommen, auf der Flucht vor der Verwüstung, die die Geißel über Lordaeron gebracht hat. Ich danke dem Licht, dass meine Familie und ich entkommen konnten, aber einige unserer wertvollen Erbstücke befinden sich noch immer in den Pestländern.\n\nWenn Ihr diese Erbstücke aus ihrer Ruhestätte in der Krypta von Trauerhügel holen könntet, damit ich sie sicher in den Katakomben der Kathedrale beisetzen kann, wäre ich Euch zutiefst dankbar.", sourceObjective = "Holt die Erbstücke aus der Krypta von Trauerhügel in den westlichen Pestländern und kehrt dann zur Hohepriesterin Laurena in der Kathedrale von Sturmwind zurück.", progress = "Seid Ihr aus den Pestländern zurück?", completion = "Danke, {name}. Ihr sagt, Ihr habt ein Tagebuch gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[84321] = { id = 84321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Lichts", description = "Ich bin fasziniert von dem Artefakt, das in dem von Euch gefundenen Tagebuch erwähnt wird. Es könnte das sein, dass es genau das ist, was wir im Kampf gegen die Geißel brauchen.\n\nDie meisten der noch erhaltenen Aufzeichnungen aus Andorhal befinden sich unter dem Schutz des Scharlachroten Kreuzzugs in Hearthglen. Durchsucht sie und versucht, weitere Informationen zu finden.", sourceObjective = "Reist nach Hearthglen in den westlichen Pestländern und sucht nach Informationen über das im Tagebuch beschriebene Artefakt.", completion = "Dieses Geschäftsbuch scheint Aufzeichnungen über die Aktivitäten des Scharlachroten Kreuzzugs in den Pestländern zu enthalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84322] = { id = 84322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Forschung", description = "Eine Seite des Geschäftsbuchs fällt Euch ins Auge:\n\n\"Artefakt, in der Nähe der Krypta von Trauerhügel gefunden. Starke Abstimmung auf das Licht. Schlechter Kandidat für das LW-Projekt aufgrund der Schutzwirkung und des Widerstands gegen Verstärkungszauber. Zur weiteren Untersuchung nach Tyrs Hand gebracht.\"", sourceObjective = "Sucht nach dem Artefakt in der Festung des Scharlachroten Kreuzzugs bei Tyrs Hand in den östlichen Pestländern.", completion = "Beim Öffnen des Spinds findet Ihr eine kleine Kiste. Ist es das, wonach Ihr gesucht habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[84323] = { id = 84323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis im Inneren", description = "Aus der Kiste dringt Energie nach außen. Das muss das Artefakt sein! Jetzt müsst Ihr die Kiste nur noch öffnen...", sourceObjective = "Findet einen Weg, die Kiste zu öffnen und das Artefakt zu bergen. Bringt es dann zur Hohepriesterin Laurena in der Kathedrale von Sturmwind.", progress = "Was habt Ihr gefunden, {name}?", completion = "Die Geschichte war also wahr... Ich werde das hier aufbewahren und sein Potenzial untersuchen. Das könnte die Verteidigung gegen die Geißel sein, die wir brauchen.\n\nNehmt dies, {name}. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[84324] = { id = 84324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Annäherungsversuche", description = "{name}, als ich den Lichtsplitter untersuchte, den Ihr mitgebracht habt, gewährte er mir Visionen. Ich sehe einen Priester der Horde, der einen ähnlichen Splitter findet, und ich sehe die Allianz und die Horde in einer Lichtwelle zusammenkommen.\n\nLeider haben sich unsere Beziehungen zur Horde weiter verschlechtert.\n\nIch schlage vor, ein diplomatisches Geschenk als Geste des guten Willens zusammenzustellen. Bringt mir diese Waren und wir werden sehen, ob wir einen Dialog zwischen unseren Völkern beginnen können.", sourceObjective = "Holt die Vorräte und bringt sie zur Hohepriesterin Laurena in der Kathedrale von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[84325] = { id = 84325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrein der Zusammenarbeit", description = "Am Fuß der Statue lässt sich eine Platte herausschieben, die ein Stück Pergament und einen strahlenden Kristall freigibt, der dem ähnelt, den Ihr bei Tyrs Hand entdeckt habt.", sourceObjective = "Überbringt der Hohepriesterin Laurena in der Kathedrale von Sturmwind den Kristall.", sourceObjectiveStatus = "unverified-source-field" }
quests[84326] = { id = 84326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatenring", description = "Das diplomatische Geschenk, das Ihr zusammengestellt habt, ist beim Priester der Verlassenen Dietrich Praice angekommen, und ich habe diskret Kontakt mit ihm aufgenommen. Wir sind uns beide einig, dass diese Suche unter den Gläubigen bleiben sollte. Wenn die Splitter als Waffe verwendet werden können, ist es am besten, wenn sie nicht in die Hände der Anführer einer der Fraktionen fallen.\n\nWir haben eine geheime Erkennungsmethode für diejenigen entwickelt, die nach den Splittern suchen. Bringt mir Materialien, um einen Ring zu schmieden, der ein Fragment von einem der Splitter enthält.", sourceObjective = "Überbringt der Hohepriesterin Laurena in der Kathedrale von Sturmwind die gewünschten Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[84327] = { id = 84327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine diplomatische Mission", description = "Eure nächste Aufgabe wird recht schwierig, {name}. \n\nIhr müsst Kontakt mit einem Priester der Horde aufnehmen, der die Splitter sucht. Anhand der Ringe könnt Ihr einander erkennen. Man wird Euch nach Orgrimmar begleiten, wo Ihr mit Dietrich Praice sprechen müsst.\n\nWenn Ihr die Priester der Horde davon überzeugen könnt, dass unsere Absichten friedlich sind, haben wir vielleicht eine Chance, die Splitter wieder zu vereinen.", sourceObjective = "Nehmt Kontakt mit einem Priester der Horde an den Toren von Orgrimmar auf und erlangt diplomatische Immunität, indem beide Seiten ihre Diplomatenringe verwenden. Begebt Euch dann nach Orgrimmar und sprecht mit Dietrich Praice. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84328] = { id = 84328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur des Splitters", description = "Ich bin bereit, zu glauben, dass Ihr mit guten Absichten hier seid, {class}.\n\nWir sind für ein Treffen zwischen unseren Völkern offen. Aber der Lichtsplitter, den wir besitzen, ist in schlechtem Zustand. Wir müssen ihn aufladen, bevor wir versuchen, ihn mit den anderen zu vereinen.\n\nDie alten Hochgeborenen des heutigen Düsterbruchs waren Experten im Manipulieren arkaner und heiliger Energien. Geht dorthin und findet alle Informationen, die Ihr über Artefakte des Lichts finden könnt. Kehrt dann zu mir zurück.", sourceObjective = "Holt das Buch \"Angewandte Göttlichkeit\" aus Düsterbruch und kehrt dann zu Dietrich Praice in Orgrimmar zurück.\n\nUm Orgrimmar zu betreten und diplomatische Immunität zu erlangen, benötigt Ihr die Hilfe eines Hordenpriesters mit einem Diplomatenring. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84329] = { id = 84329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Synode kommt zusammen", description = "Glaubensvertreter von Allianz und Horde haben vereinbart, sich zu treffen und die Splitter zu vereinen. Es gibt eine Kapelle neben der Turmruine von Karazhan, die als neutraler Ort dienen wird. \n\nEuer Ring enthält den letzten Splitter. Wenn Ihr da seid, kann die Beschwörung beginnen.", sourceObjective = "Sprecht mit Maethra Schlackherz auf dem Gebirgspass der Totenwinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[84330] = { id = 84330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines bisschen Nekromantie", description = "Ihr seht also, wir müssen eine passende Zwergenleiche finden und ein kleines Ritual mit ihr durchführen, um meinen Geist zu erden, damit ich meinen Weg finden kann! Alles ganz normale Dinge! Wir brauchen natürlich auch einen Teil eines nekrotischen Runensteins von einem Nekromanten. Ich hörte, es gibt einen in Stratholme. Er nennt sich Maleki der Leichenblasse oder so ähnlich. Ich kann mir nicht vorstellen, dass er ihn freiwillig hergibt, aber dafür gibt es eine Lösung!\n\nGebt mir den Stein und geht dann zum Tiefgewölbe. Dort findet Ihr eine passende Leiche!", sourceObjective = "Besorgt Euch einen nekrotischen Runenstein von Maleki dem Leichenblassen in Stratholme und findet dann die verwesende Zwergenleiche in der Nähe des Tiefgewölbes im südwestlichen Teil der östlichen Pestländer.", completion = "<Ihr greift nach der Leiche und Euch stellen sich die Nackenhaare auf... Ihr habt ein ungutes Gefühl bei der ganzen Sache.>", sourceObjectiveStatus = "unverified-source-field" }
quests[84331] = { id = 84331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wunder", description = "Die Splitter sind vollständig, {name}. Nun fehlt nur noch Euer Ring.", sourceObjective = "Wendet Euren Diplomatenring auf die Scherben an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84332] = { id = 84332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dankbarkeit eines Thans", description = "<Ihr hört eine geisterhafte Stimme in Eurem Kopf, als Ihr die kleine Truhe berührt> \n\nKann Euch nicht genug danken, {name}. So habt Ihr Euch das sicher nicht vorgestellt! Damit Ihr nicht zu sauer seid, habe ich etwas für Euch, das ich nicht mehr brauche und das Euch von Nutzen sein könnte.\n\nViel Glück, {name}. Ach, eins noch... Wenn Ihr eines Tages eine riesige schwimmende Nekropole in der Ferne seht, würde ich an Eurer Stelle die Flucht ergreifen. Hah!Ihr erlernt:", sourceObjective = "Ihr findet einen kleinen Runenstein auf dem Boden der Truhe...", sourceObjectiveStatus = "unverified-source-field" }
quests[84338] = { id = 84338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbindlicher Vertrag", description = "<Der Unterzeichner/Die Unterzeichnerin> bestätigt hiermit die Echtheit des Sulfuronblocks, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird. <Der Unterzeichner/Die Unterzeichnerin> erkennt ebenso an, dass TB Ltd. keinerlei Verantwortung oder Haftung für jeglichen Schaden übernimmt, der <ihm/ihr> infolge des Versuchs, Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen, widerfahren könnte.\n\nMit Unterzeichnung dieses Vertrags wird allen darin aufgeführten Bedingungen zugestimmt.\n\n_________________\n\nUnterschrift", sourceObjective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84348] = { id = 84348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primärziel: Herzog Tektonis", description = "Ein besonders fieser Elementar namens Tektonis hat am Fuße des Schwarzfelsens das Sagen, und er muss einfach verschwinden! Erledigt diesen Steinhaufen und meldet Euch bei mir, wenn es vollbracht ist!\n\nIhr findet Herzog Tektonis in einem Tal im Südosten, nahe dem Eingang zum Schwarzfels.", sourceObjective = "Hansel Bleihand in Thoriumspitze möchte, dass Ihr Herzog Tektonis vernichtet. Herzog Tektonis befindet sich in einem kleinen Tal westlich des Eingangs der sengenden Schlucht, nahe des Eingangs zum Schwarzfels.", completion = "Das wird ein herber Schlag für unsere Feinde sein, {name}! Huzzah!", sourceObjectiveStatus = "unverified-source-field" }
quests[84349] = { id = 84349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primärziel: Herzog Sengbrand", description = "Unsere Späher berichten, dass ein Feuerlord, der sich selbst Herzog Sengbrand nennt, in den Tiefen des Kessels nach Kräften versucht, weitere Feuerelementare aus den Feuerlanden zu beschwören! Ihr müsst dort hineingehen und der Sache Einhalt gebieten, bevor sie außer Kontrolle gerät.", sourceObjective = "Hauptmann des Ausgucks Lolo Langhieb will, dass Ihr Herzog Sengbrand vernichtet. Herzog Sengbrand befindet sich in den tiefsten Höhlen der Schlackengrube, direkt südlich von Thoriumspitze.", completion = "Gut gemacht, {name}! Nach der ganzen Anstrengung brauche ich einen Drink! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[84350] = { id = 84350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermalmung", description = "Diese Erdelementare sind überall! Verpasst ihnen eine ordentliche Tracht Prügel und schickt sie zurück in die Feuerlande!", sourceObjective = "Evonice Sootsmoker möchte, dass Ihr 10 Obsidianhäscher in der Sengenden Schlucht tötet. Die Obsidianhäscher sind im gesamten südlichen Teil der Sengenden Schlucht und in der Nähe des Eingangs zum Blackrock zu finden.", completion = "Hah! Das wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[84351] = { id = 84351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effizienz ist Trumpf", description = "Seit die Ausbrüche begonnen haben, kämpfen wir mit allen Mitteln gegen diese verfluchten Elementare, und die Anstrengungen fordern ihren Tribut von unseren Handwerkern. Offensichtlich ist es eine Menge Arbeit, die Ausrüstung der Truppen in einem tadellosen Zustand zu halten. Glücklicherweise sind wir Zwerge Meister darin, unsere Effizienz zu steigern, und wir haben herausgefunden, dass die Energiekerne in den Obsidianwogern südöstlich von Thoriumspitze als Schleifsteine für unsere Klingen verwendet werden können! \n\nWürdet Ihr mehr für uns holen?", sourceObjective = "Zuchtmeister Skrange möchte, dass Ihr Obsidianwoger in der sengenden Schlucht tötet und ihre Kraftkerne zu ihm bringt. Obsidianwoger findet Ihr im südlichen Teil der sengenden Schlucht, in der Nähe des Eingangs zum Schwarzfels.", progress = "Hm?", completion = "Das wird reichen, {class}. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[84355] = { id = 84355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenbringer auf Sparflamme", description = "Als hätten wir hier nicht schon genug zu tun, herrscht auch noch in der Enklave Schattenhammer westlich von Thoriumspitze emsiges Treiben, seit der Berg in die Luft geflogen ist. Soweit wir das beurteilen können, haben die neuen Flammenbringer jetzt das Sagen. \n\nSchaut doch mal dort vorbei und legt so viel um, wie Ihr könnt.", sourceObjective = "Zuchtmeister Skrange möchte, dass Ihr die Verteidiger und Elementarmagier der Flammenbringer auf dem Feuerwachtgrat westlich von Thoriumspitze tötet.", completion = "Auf Nimmerwiedersehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84356] = { id = 84356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, welch Glanz!", description = "Vor Kurzem wurde eine Gruppe von Dunkeleisenzwergen gefangen genommen, die einige ausgesprochen seltsame verzauberte Edelsteine bei sich trugen. Diese Edelsteine scheinen in Azeroth nicht heimisch zu sein, und ich MUSS sie einfach weiter erforschen! Ihre Sklaven graben das Zeug jetzt tief im Kessel aus, und Ihr müsst Euch so schnell wie möglich auf den Weg dorthin machen und mir ein paar zusätzliche Proben bringen. Es wird sich für Euch lohnen!", sourceObjective = "Meisterschmied Burninate in Thoriumspitze möchte, dass Ihr 8 Flammensteinsplitter von den Sklaventreibern der Dunkeleisenzwerge in der Schlackengrube sammelt. Den Eingang zur Schlackengrube findet Ihr im Kessel, südöstlich von Thoriumspitze.", progress = "Was habt Ihr für mich?", completion = "Sie sind wunderschön! Ich kann es kaum erwarten, sie unter mein Monoskop zu legen. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84359] = { id = 84359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlaflose Nächte", description = "Es reicht nicht, dass diese Hunde uns angreifen, wenn wir wach sind, sie müssen uns auch angreifen, wenn wir schlafen! Der neue Zwielichtfürst hat eine besondere Vorliebe für Traumschwindeleien, also schickt er Attentäter, die uns in unseren Träumen angreifen! Ich möchte, dass Ihr ein paar Schlucke von meinem speziell zubereiteten, regional bezogenen, nicht gentechnisch veränderten \"Traumsaft\" zu Euch nehmt. Der sollte es Euch ermöglichen, die Grenze zwischen der Wach- und der Traumwelt zu überqueren und diese Attentäter aufzuhalten.", sourceObjective = "Evonice Rußraucher bittet Euch, den speziell zubereiteten Traumsaft zu trinken und 5 Flammenbringerpirscher in der Nähe von Thoriumspitze in der sengenden Schlucht zu töten.", completion = "Gut gemacht, {name}. Jetzt überlegen sie es sich bestimmt zweimal, bevor sie sich wieder nach Thoriumspitze schleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84360] = { id = 84360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandbekämpfung", description = "Ihr da, Ihr wurdet gerade einberufen! Die Feuerelementare strömen unaufhörlich aus dem Kessel. Ihr musst da reingehen und die Wunde ausbrennen, wenn Ihr versteht, was ich meine. Reißt Euch zusammen, Soldat!", sourceObjective = "Aufseher Schlickfaust möchte, dass Ihr 15 Feuerlandeindringlinge im Kessel, südlich von Thoriumspitze, tötet.", progress = "Ja?", completion = "Gut gemacht, {name}. Ihr habt Mumm, das muss ich Euch lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84369] = { id = 84369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung des Heilers", description = "Ich brauche Eure Hilfe. Mein Fläschchen wurde mir von den verderbten Treants des Eisenwalds innerhalb des Teufelswalds gestohlen. Die Kräutermischung sollte mir bei meinen Wunden helfen, aber sie allein wird nicht ausreichen. Bringt sie zu den heißen Quellen von Winterspring. Das heilende Wasser dort wird meine Genesung unterstützen.", sourceObjective = "Holt Euch das ungewöhnliche Fläschchen von den Eisenwaldstampfern und bringt es zu den Frostfeuerquellen in Winterspring.", progress = "Ihr habt es geschafft, {name}.", completion = "Ich danke Euch, {class}. Ihr habt mir viel Zeit erspart, indem Ihr mir mein Fläschchen gebracht habt. Damit wird sich die Verderbnis wesentlich schneller ausbreiten.\n\nLeider wird dies das letzte Mal sein, dass Ihr gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84372] = { id = 84372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lavatauchen", description = "Unsere Späher sagen mir, dass ein großer glühender Stein aus dem tiefsten Teil der Lavabecken unter dem Kessel ragt. Die Elementare scheinen auf dieses Material zu reagieren, also müsst Ihr Euch dort hineinschleichen und mir ein Stück von diesem Felsen holen. Da es dort unten in mehrfacher Hinsicht ziemlich heiß ist, solltet Ihr einen ordentlichen Vorrat an Feuerschutztränken mitnehmen!", sourceObjective = "Bringt Hansel Bleihand einen Brocken schimmerndes geschmolzenes Mineral. Ihr könnt das schimmernde geschmolzene Gestein in den Lavabecken der Schlackengrube tief im Kessel finden.", progress = "Was habt Ihr denn da?", completion = "Wir hoffen, dass wir auf diese Weise ein wenig mehr darüber erfahren können, womit wir es zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84377] = { id = 84377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Dunklen Horde", description = "Die Tat ist vollbracht. Dal'rend Blackhand, Kriegshäuptling der Dunklen Horde, liegt tot zu Euren Füßen. Nehmt seinen Kopf und zeigt ihn Meister Shaw.", sourceObjective = "Bringt den Kopf von Rend Blackhand zu Meister Mathias Shaw in Stormwind.", progress = "Beim Licht!", completion = "Gut gemacht, Champion. Der Kriegshäuptling der Dunklen Horde ist tot, und damit endet ein Zeitalter des Schreckens in unserem Land. Lasst ganz Sturmwind von Eurem Sieg wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84384] = { id = 84384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Täuschungen", description = "Ich habe von einem Gift gehört, das im Eschental an Kraft gewinnt, auf dem verdorbenen Land, wo der große Dämon Mannoroth getötet wurde. Jemand zieht Kraft aus den Überresten des Grubenlords.\n\nSie müssen Illusionen verwenden, um ihre Rituale zu verbergen. Wenn Ihr sie aufhalten wollt, müsst Ihr Euch vor ihren Täuschungen schützen.\n\nMein Stamm verwendet einen Extrakt aus Eulenbestiendrüsen in einem Zauber, um Wahrheit von Lüge zu unterscheiden. Sammelt diese Drüsen von den Eulenbestien in Winterspring.", sourceObjective = "Sammelt 6 Zirbeldrüsen von Eulenbestien in Winterspring und kehrt dann zum Schattenzahn-Abgesandten im Teufelswald zurück.", progress = "Die Verzauberung ist fast fertig, {name}. Habt ihr mitgebracht, worum ich Euch gebeten habe?", completion = "<Der Troll spricht einen Zauberspruch über einem Gegenstand und gibt ihn Euch dann.>\nNehmt das, {name}. Dieser Gegenstand wird Euch vor den Illusionen der Dämonen schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84394] = { id = 84394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Freund der Bibliothek", sourceObjective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[84395] = { id = 84395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untote Kartoffeln", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
