quests[84402] = { id = 84402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmaleins der Nekromantie", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[84405] = { id = 84405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Erbe", description = "Bevor mich die Geißel verwandelte, war ich ein bedeutender Kaufmann in Andorhal. Die Stadt hat wahrscheinlich meine damaligen Reichtümer und meine Familienaufzeichnungen in der Krypta von Trauerhügel vergraben, als man mich für tot hielt.\n\nWärt Ihr so freundlich, meine Besitztümer aus der Krypta zu holen und sie mir zurückzugeben?", sourceObjective = "Holt die Erbstücke aus der Krypta von Trauerhügel in den westlichen Pestländern zurück und bringt sie zu Dietrich Praice in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84406] = { id = 84406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikt des Lichts", description = "Diese im Tagebuch beschriebene Waffe des Lichts bereitet mir Sorgen. Wenn der Scharlachrote Kreuzzug oder die Allianz so etwas in die Hände bekommen, könnte dies eine ernsthafte Bedrohung für die Verlassenen darstellen.\n\nDie meisten der noch existierenden Aufzeichnungen aus Andorhal stehen in Hearthglen unter dem Schutz des Scharlachroten Kreuzzugs. Durchsucht sie und findet weitere Informationen.", sourceObjective = "Reist nach Hearthglen in den westlichen Pestländern und sucht nach Informationen über das im Tagebuch beschriebene Artefakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84407] = { id = 84407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis im Inneren", description = "Aus der Kiste dringt Energie nach außen. Das muss das Artefakt sein! Jetzt müsst Ihr die Kiste nur noch öffnen...", sourceObjective = "Findet einen Weg, die Kiste zu öffnen und das Artefakt zu bergen. Bringt es dann zu Dietrich Praice in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84408] = { id = 84408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatische Annäherungsversuche", description = "{name}, als ich den Lichtsplitter untersuchte, den Ihr mitgebracht habt, gewährte er mir Visionen. Ich sehe einen Priester der Allianz, der einen ähnlichen Splitter findet, und ich sehe die Allianz und die Horde in einer Lichtwelle zusammenkommen.\n\nLeider behandelt uns die Allianz weiterhin wie Ungeziefer.\n\nIch schlage vor, ein diplomatisches Geschenk als Geste des guten Willens zusammenzustellen. Bringt mir diese Waren und wir werden sehen, ob wir einen Dialog zwischen unseren Völkern beginnen können.", sourceObjective = "Holt die Waren und bringt sie zu Dietrich Praice in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84410] = { id = 84410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrein der Zusammenarbeit", description = "Am Fuß der Statue lässt sich eine Platte herausschieben, die ein Stück Pergament und einen strahlenden Kristall freigibt, der dem ähnelt, den Ihr bei Tyrs Hand entdeckt habt.", sourceObjective = "Bringt den Kristall zu Dietrich Praice in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84411] = { id = 84411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatenring", description = "Das diplomatische Geschenk, das Ihr zusammengestellt habt, ist bei Hohepriesterin Laurena in Sturmwind angekommen, und ich habe diskret Kontakt mit ihr aufgenommen. Wir sind uns beide einig, dass diese Suche unter den Gläubigen bleiben sollte. Wenn die Splitter als Waffe verwendet werden können, ist es am besten, wenn sie nicht in die Hände der Anführer einer der Fraktionen fallen.\n\nWir haben eine geheime Erkennungsmethode für diejenigen entwickelt, die nach den Splittern suchen. Bringt mir Materialien, um einen Ring zu schmieden, der ein Fragment von einem der Splitter enthält.", sourceObjective = "Bringt die gewünschten Materialien zu Dietrich Praice in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84412] = { id = 84412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine diplomatische Mission", description = "Eure nächste Aufgabe wird recht schwierig, {name}.\n\nIhr müsst Kontakt mit einem Priester der Allianz aufnehmen, der die Splitter sucht. Anhand der Ringe könnt Ihr einander erkennen. Man wird Euch in die Kathedrale von Sturmwind begleiten, wo Ihr mit Hohepriesterin Laurena sprechen müsst.\n\nWenn Ihr die Priester der Allianz davon überzeugen könnt, dass unsere Absichten friedlich sind, haben wir vielleicht eine Chance, die Splitter wieder zu vereinen.", sourceObjective = "Nehmt Kontakt mit einem Priester der Allianz an den Toren von Sturmwind auf und erlangt diplomatische Immunität, indem beide Seiten ihre Diplomatenringe verwenden. Betretet dann die Kathedrale von Sturmwind und sprecht mit Hohepriesterin Laurena. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84413] = { id = 84413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur des Splitters", description = "Ich bin bereit, zu glauben, dass Ihr mit guten Absichten hier seid, {class}.\n\nWir sind für ein Treffen zwischen unseren Völkern offen. Aber der Lichtsplitter, den wir besitzen, ist in schlechtem Zustand. Wir müssen ihn aufladen, bevor wir versuchen, ihn mit den anderen zu vereinen.\n\nDie alten Hochgeborenen des heutigen Düsterbruchs waren Experten im Manipulieren arkaner und heiliger Energien. Geht dorthin und findet alle Informationen, die Ihr über Artefakte des Lichts finden könnt. Kehrt dann zu mir zurück.", sourceObjective = "Holt das Buch \"Angewandte Göttlichkeit\" aus Düsterbruch und kehrt dann zu Hohepriesterin Laurena in der Kathedrale von Sturmwind zurück.\n\nUm Sturmwind zu betreten und diplomatische Immunität zu erlangen, benötigt Ihr die Hilfe eines Allianzpriesters mit einem Diplomatenring. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84414] = { id = 84414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mich auf den Weg!", description = "<Ihr hört die körperlose Stimme von Orthas in Eurem Kopf.>\n\nDa wären wir. Ziehen wir's durch, ja?", sourceObjective = "Beobachtet Orthas, während er diese Welt verlässt.", completion = "Euch fehlen die Worte für das gerade Geschehene. Was habt Ihr getan? \n\nHoffentlich findet sich in dieser Truhe wenigstens gute Beute.", sourceObjectiveStatus = "unverified-source-field" }
quests[84418] = { id = 84418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Ritter", sourceObjective = "Ein gemeinsamer Freund von uns hat kürzlich um Hilfe bei der Suche nach einem vermissten Ritter namens Dalton gebeten. Er und sein junger Knappe wurden zuletzt in den Pestländern gesehen und man hat schon seit einiger Zeit nichts mehr von ihnen gehört. Falls Euch Eure Reisen dorthin führen, haltet bitte nach ihnen Ausschau.\n\nEs gibt nicht gerade viele Hinweise, aber Ihr habt die Gabe, in alle möglichen interessanten Situationen zu geraten. Wenn jemand inmitten dieser höllischen Pestländer über einen vermissten Ritter und seinen Knappen stolpern könnte, dann Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[84495] = { id = 84495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Plattenstulpen", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, {name}. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.", sourceObjective = "Bringt Malyfous Düsterhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84496] = { id = 84496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", sourceObjective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84525] = { id = 84525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überirdischer Schatz", sourceObjective = "Bitteschön, Boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[84545] = { id = 84545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belohnung eines Helden", description = "{name}, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben.\n\nWir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall... ist eine Belohnung mehr als angebracht.\n\nUnter der Brandung an der südlichen Basis der Insel findet Ihr einen Kasten. In diesem werdet Ihr Eure... Belohnung finden.\n\nGeht, {name}. Nehmt Euch Eure Belohnung.", sourceObjective = "Nehmt Eure Belohnung aus Hydraxis' Truhe.", completion = "Hydraxis' Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, {name}. Möge es Euch vor den Feinden des Wasserlords schützen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[84546] = { id = 84546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holzstab der Uralten", description = "Agenten der Brennenden Legion sind noch immer in unserer Welt aktiv, {class}. Diese Agenten verderben alles, was ihnen unterkommt. Die Natur welkt und siecht in ihrer Gegenwart dahin.\n\nIhr müsst diese dämonischen Verderber aufspüren und zerstören, {name}. Seid gewarnt, Ihr müsst sie selbst angreifen, andernfalls werden sie fliehen. Solange Ihr alleine seid, werden sie versuchen Euch zu zerstören. Ihr müsst sie bekämpfen und ihren Hochmut zu ihrem Verderben werden lassen.\n\nIch gewähre Euch ein Stück meiner Rinde, mögen die Inschriften Euch zu Eurem Ziel führen.", sourceObjective = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:\n\nSimone die Verführerin.\n\nKlinfran der Wahnsinnige.\n\nSolenor der Schlächter.\n\nArtorius der Verhängnisvolle.\n\nVernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.\n\nHaltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.\n\nIhr MÜSST diese Aufgabe eigenständig erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84548] = { id = 84548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona: Eine Studie über Heimlichkeit und Verrat", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", sourceObjectiveStatus = "unverified-source-field" }
quests[84549] = { id = 84549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arkanistenkochbuch", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84550] = { id = 84550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodex der Verteidigung", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, {race}. Solltet Ihr noch weitere Folianten finden, zögert nicht, sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", sourceObjectiveStatus = "unverified-source-field" }
quests[84551] = { id = 84551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Licht und wie man es schwingt", description = "Der Foliant trägt das Zeichen des Athenaeums.", sourceObjective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84555] = { id = 84555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nostros Kompendium", description = "Ihr habt etwas von großer Bedeutung entdeckt. Dieses Buch ist nicht wie all die anderen, die Ihr gesehen habt.\n\nEs scheint, als hätte jemand... oder etwas... es geschafft, das Siegel des Athenaeums zu brechen. Die Schrift im Inneren ist wirr und lässt sich kaum lesen.", sourceObjective = "Bringt Nostros Kompendium des Drachentötens zum Athenaeum zurück.", progress = "Ah, eines unsere größten Sammelwerke. Das hat schon seit Ewigkeiten gefehlt.", completion = "Auf dem Schwarzmarkt hättet Ihr für dieses Buch ein hübsches Sümmchen kassiert, {name}. Insbesondere, da das Schutzsiegel gebrochen wurde, wodurch die Geheimnisse des Drachentötens allen zugänglich wäre, die über den nötigen Intellekt verfügen, das Wissen auf diesen heiligen Seiten in sich aufzunehmen.\n\nEs ist wohl eine große Belohnung fällig... Nun, eine Belohnung, die gewaltiger Mühen bedarf, um sie Euch zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84556] = { id = 84556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden von Quel'Serrar", description = "Wenn Ihr diesen Auftrag annehmen möchtet, dann präsentiert Lydros die stumpfe Klinge.", sourceObjective = "Gebt Hüter des Wissens Lydros die stumpfe und glanzlose Elfenklinge.", progress = "Exzellent, lasst uns beginnen...", completion = "Wenn Ihr es schafft, den Drachenhort zu betreten, die Klinge unter ihrem feurigen Atem zu erhitzen und sie anschließend in ihrem Blut zu härten, dann werde ich sie für Euch binden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84557] = { id = 84557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden von Quel'Serrar", description = "Nehmt die unbefeuerte uralte Klinge zu Onyxias Hort und stellt Euch ihr im Kampf.\n\nEs bedarf einer List, um die Klinge zu erhitzen. Während Ihr Euch im Kampf befindet, wird sie mit Sicherheit versuchen, Euch mit ihrem Feueratem einzuäschern. Platziert die unbefeuerte Klinge in der Nähe und hofft, dass der Feueratem die Klinge erhitzt. Wenn Ihr all das überlebt, dann nehmt die uralte Klinge und erlegt den Drachen.\n\nTaucht die erhitzte uralte Klinge anschließend in Onyxias schwelenden Leichnam, um die behandelte uralte Klinge zu erhalten.", sourceObjective = "Ihr müsst Onyxia dazu bringen, ihren Feueratem auf die unbefeuerte uralte Klinge zu richten. Sobald das erledigt ist, könnt ihr die nun erhitzte uralte Klinge wieder aufnehmen. Aber seid gewarnt, die erhitzte uralte Klinge wird nicht ewig heiß bleiben... es ist also Eile geboten.\n\nFür den letzten Schritt müsst Ihr die Bestie töten und die erhitzte uralte Klinge in ihren Leichnam versenken, bevor Ihr zu mir zurückkehren könnt.\n\nTut das, und Quel'Serrar wird Euer sein.", progress = "Möglicherweise wird eines Tages jemand anderes die prismatische Klinge führen.", completion = "<Lydros murmelt unverständlich vor sich hin.>\n\nWie versprochen, {class}, die Klinge von Quel'Serrar.", sourceObjectiveStatus = "unverified-source-field" }
quests[84560] = { id = 84560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Zeiten feiern", description = "Sucht Major Mattingly im Tal der Helden auf, {name}. Er erwartet Euch bereits...", sourceObjective = "Sucht Major Mattingly im Tal der Helden auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[84561] = { id = 84561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für alle sichtbar", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Thrall salutiert Euch.>\n\nLasst Euer Publikum nicht warten, großer Held.", sourceObjective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[84590] = { id = 84590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waage von Licht und Schatten", description = "Ihr müsst tun, was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegenlaufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr habt versagt.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, {name}.", sourceObjective = "Rettet 50 Arbeiter, bevor 15 getötet werden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen, wie viele Arbeiter bereits getötet wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84636] = { id = 84636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streuner", description = "Die Druiden mach'n sich Sorg'n wegen eines Erdfragments in den Grabhügeln östlich des Sees. Es wird von wütenden Erdelementaren bewacht, die die Druiden davon abhalt'n, ihre Riten durchzuführ'n.\n\nSteigt in die Grabhügel hinab und holt Euch das Elementarfragment. Nehmt meine Katze, Siopi, mit, um an den Elementaren vorbeizuschleich'n, falls Ihr selbst keinen Katzenbegleiter habt. Siopi liegt wahrscheinlich irgendwo in der Nähe im Gras und schläft.", sourceObjective = "Reist zu den Grabhügeln im Osten von Moonglade auf Kalimdor. Steigt in den südöstlichsten Grabhügel des Stormrage hinab und sucht in den Tiefen nach dem Erdelementarfragment. Verwendet die Fertigkeit 'Schleichen' Eures Tierbegleiters, um an den Wächtern vorbeizukommen und ein Fragment eines Erdelementar zu bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84777] = { id = 84777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn für Nafien", progress = "Ihr habt Euch mir gegenüber mehr als bewiesen, doch um das Vertrauen meiner misstrauischen Brüder und Schwestern zu gewinnen, ist es noch ein weiter Weg. Keine Sorge, ich werde Euch dabei behilflich sein, auch diese letzte Hürde zu überwinden.\n\nEinige Furbolgs der Totenwaldfelle tragen einen auffälligen Kopfschmuck. Dieser wäre ein ausreichender Beweis, für Euren Kampf gegen unsere verderbten Geschwister. Bringt mir die Federn der von Euch erbeuteten Kopfschmucke. Für jeweils fünf Federn die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.", completion = "Gut gemacht, {name}! Ich werde dafür Sorgen, dass alle Furbolgs der Holzschlundfeste von Euren Taten erfahren.\n\nVergesst nicht, mir alle Federn zu bringen, die Ihr findet." }
quests[84853] = { id = 84853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren im Schnee", description = "Ihr habt gute Arbeit geleistet. Ich werd' Euch helf'n. Als ich Van Amburgh das letzte Mal geseh'n hab, hatte er 'ne Menagerie aus drei Tier'n bei sich, 'ne Großkatze, 'nen Raptor und 'nen monströs'n Käfer. Er hält sie in Käfigen, peitscht sie aus, macht sie richtig wütend. Grausamkeit und Hunger sind seine Erziehungsmaßnahmen. Hab vor 'ner Weile in Feralas geg'n ihn gekämpft, keine Ahnung, wo er grade is'.\n\nIhr solltet Euch mit Estelenn treff'n un' seh'n, ob sie Eure Hilfe braucht. Und richtet ihr Grüße von mir aus.", sourceObjective = "Reist zu den Hügeln in Winterspring im Norden von Kalimdor, nördlich von Everlook, und trefft Euch dort mit Estelenn, um zu erfahren, wie Ihr ihr helfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84870] = { id = 84870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Hort", description = "Das Dokument ist ein Bericht von einem von Razorgores Untergebenen. Es gibt Gerüchte, dass einige der Blackrock-Orcs verbotene magische Artefakte im Lagerhaus verstecken. Es ist ungewiss, ob es sich um eine einfache Schmuggelaktion handelt oder ob mehr dahintersteckt.\n\nWie dem auch sei, es hört sich nach einer lukrativen Sache an. Geht lieber allein, damit Ihr nicht entdeckt werdet. Dann braucht Ihr auch die Beute nicht teilen.", sourceObjective = "Brecht in das Lager von Blackrockspitze ein und stehlt alle Wertsachen, die sich dort befinden. Ihr müsst den Auftrag alleine abschließen.", completion = "Ich kann sehen, dass Ihr nicht zu ihnen gehört. Ich bitte um Verzeihung.", sourceObjectiveStatus = "unverified-source-field" }
quests[84880] = { id = 84880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes", description = "Ich wurde zusammen mit einem Magier hierhergeschickt, um die Klinge des Verschlingens für das Syndikat zu stehlen. Aber als ich die Schlösser geknackt hatte, hat er mich angegriffen. Er hat sich die Klinge geschnappt und mich dem Tod überlassen.\n\nDer Name des Magiers war Caius. Er ist vor nicht allzu langer Zeit zu uns gestoßen und versprach, dass er sein Wissen über ein mächtiges Ritual mit uns teilen würde, wenn wir ihm im Gegenzug dabei helfen, die letzte Reagenz zu stehlen.\n\nDiese verräterische Schlange und sein Ritual müssen aufgehalten werden. Er darf damit nicht durchkommen!", sourceObjective = "Im Syndikat braut sich eine schreckliche Bedrohung zusammen. Jemand in Rabenholdt könnte wissen, was zu tun ist.", completion = "Ich kann verstehen, warum Ihr mir das gebracht habt, {class}. Das sind wahrlich beunruhigende Neuigkeiten. Wir müssen unseren nächsten Schritt genau durchdenken. Lasst mich kurz allein, damit ich in Ruhe nachdenken kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[84881] = { id = 84881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Feste des Schattens", description = "Caius' Verrat bereitet mir echte Sorgen. Er deutet darauf hin, dass es eine weitere, noch gefährlichere Organisation gibt.\n\nUnsere Geheimdienstinformationen lassen vermuten, dass es sich dabei um den Schattenrat handelt.\n  \nDas Hauptquartier des Rats befindet sich in der Schattenfeste im Teufelswald. Ihr müsst die Schattenfeste infiltrieren, Caius finden und ihn aufhalten.\n\nEs ist zwingend erforderlich, dass Ihr unentdeckt bleibt. Sollte Caius von Eurer Anwesenheit erfahren, wird er wahrscheinlich fliehen oder Euch töten lassen.", sourceObjective = "Findet Caius in der Schattenfeste im Teufelswald und haltet sein Ritual auf. Bringt außerdem einen Beweis seines Ablebens zu Fahrad im Rabenholdtanwesen. Ihr müsst alleine gehen und unentdeckt bleiben, bis Ihr Caius findet.", progress = "Habt Ihr Caius schon gefunden?", completion = "Caius war also in der Tat ein Verbündeter des Schattenrats. Die Konsequenzen einer solchen Verschwörung könnten gigantisch sein.\n\nDer erfolgreiche Abschluss Eurer Mission hat wertvolle Informationen zutage gebracht und eine noch größere Gefahr für Azeroth abgewendet. Herausragende Arbeit, {name}.   \n\nWas den von Euch gefundenen \"Traumfresser\" betrifft: Mich schaudert es bei dem Gedanken daran, was hätte passieren können, wenn Caius das Ritual beendet hätte. Setzt ihn mit Geschick ein und wählte Eure Ziele weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[84950] = { id = 84950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinaus in die Kälte", description = "Beim alten Lager gibt es noch etwas Holz, das nützlich sein könnte, und einen beeindruckenden Feuerstein. Wenn Ihr weitere Spuren von Estelenn finden oder auf ihre Rückkehr warten wollt, müsst Ihr Material einsammeln, um ein eigenes Lager aufzuschlagen, damit Ihr den kommenden Schneesturm überstehen könnt.\n\nIhr könnt den Sturm natürlich auch ganz vermeiden, indem Ihr die Hügel verlasst. Dann müsst Ihr allerdings zurückkommen und die nötigen Hinweise finden.", sourceObjective = "Verwendet Eure Überlebensvorräte, um ein Fundament für einen Lagerplatz und ein einfaches Zelt zu errichten.\n\nWenn Ihr Euer Fundament verliert, dann errichtet mit Euren Überlebensvorräten ein neues und bringt die Materialien an den neuen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[85030] = { id = 85030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uthers Grabmal", description = "Bevor wir überstürzte Behauptungen über die Authentizität der Probe machen, sollten wir zuerst feststellen, ob sie echt ist. Es wird gewiss nicht leicht sein, das mit Sicherheit zu sagen, doch möglicherweise erhalten wir ein paar Erkenntnisse, wenn wir die Probe zu Uthers Grabmal in den Westlichen Pestländern bringen. Sprecht dort mit dem ansässigen Priester, Thel'danis. Er ist ein gewissenhafter Gelehrter, was das Leben des Lichtbringers betrifft. Mit etwas Glück kann er die Authentizität der Probe feststellen.", sourceObjective = "Nehmt das Blut des Lichtbringers und sprecht mit Hohepriester Thel'danis, um die Authentizität des Relikts zu bestimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85034] = { id = 85034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Andorhal", description = "Überreste wie die, die Ihr bei Euch tragt, haben oft geheimnisvolle Eigenschaften. Manche besonders mächtigen Relikte können sogar empfindsam wirken oder eine Persönlichkeit haben, insbesondere, wenn sie sich in der Nähe von Individuen und Orten befinden, denen sie im Leben eng verbunden waren.\n\nWenn das wirklich Uthers Blut ist, dann reagiert es möglicherweise in der Nähe des Ortes, an dem Uther starb. Erkundet die Stadt und seht, was passiert.", sourceObjective = "Nehmt das Blut des Lichtbringers und erkundet Andorhal.", progress = "Habt Ihr Andorhal bereits erkundet? Hat das Blut auf irgendeine Weise reagiert?", completion = "Dann besteht kein Zweifel, das Blut ist echt. Was Ihr da habt, ist ein wahrer Schatz, {class}. Passt auf Euch auf und beschützt es mit Eurem Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[85061] = { id = 85061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käferjagd", description = "Ich bin Euren Spuren gefolgt und froh zu sehen, dass Ihr noch lebt! In den Überlebenskünsten seid Ihr wohl wirklich so versiert wie ich dachte. Entschuldigt, dass ich Euch warten ließ.\n\nIch habe weitere Hinweise auf unsere Beute gefunden. Van Amburgh ist irgendwo im Südwesten von Kalimdor. Ich werde dort weiter nach Spuren suchen. In der Zwischenzeit könntet Ihr Eure Schießkünste auffrischen.\n\nReist nach Silithus. Ihr könnt den Druiden der Burg Cenarius helfen, während Ihr Eure Trickschüsse übt.", sourceObjective = "Reist zur Burg Cenarius in Silithus auf Kalimdor und sprecht mit den Druiden dort über die Entwicklung der Silithiden. Helft ihnen wie verlangt, währen Ihr Eure Schießkünste trainiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[85063] = { id = 85063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhepunkt", description = "Ich bin mir nicht sicher, was passiert, sobald wir das Ritual beginnen. Dieser Ort wimmelt nur so vor Dämonen und wenn sie unser Ritual entdecken, müssen wir uns vermutlich verteidigen. Ihr und Ada müsst Euch darum kümmern, während ich den Zauber kanalisiere. Doch bleibt in der Nähe, da Ihr selbst bedeutend für diese Magie seid.", sourceObjective = "Verteidigt Gregory, während er das Ritual abschließt, um die Echokugel der Mannoroc zu zerstören.", progress = "Seid auf der Hut, {class}!", completion = "Nein... nein. Das kann nicht sein! Wir waren so kurz davor!\n\nMeine Mission ist gescheitert. Azgaloth wurde befreit. Wir müssen uns wieder sammeln und unsere nächsten Schritte planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85064] = { id = 85064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlimmste Fall", description = "Es ist nun ein Rennen gegen die Zeit. Der Schreckenslord hat den Demonfall-Canyon erwähnt, die gute Nachricht ist also, dass wir wissen, wohin er geht. Die schlechte Nachricht ist, dass wir vermutlich Azgaloths Verbindung zu Azeroth gestärkt haben. Selbst wenn wir jetzt Azgaloth töten, würde er sich bald selbst manifestieren.\n\nIch habe eine Idee. Sie ist verzweifelt, aber sie ist unsere einzige Hoffnung. Es gibt jemanden in Andorhal mit besonderen Fähigkeiten, die uns möglicherweise weiterhelfen können, doch wir müssen erst ihr Vertrauen gewinnen.", sourceObjective = "Reist nach Andorhal und findet Gregory, um herauszufinden, was als Nächstes zu tun ist.", progress = "Ihr habt es geschafft. Gut.", completion = "Das Reliquiar mit Uthers Blut war der Schlüssel für das Ritual, aber es ging während des Angriffs leider verloren. Wie ich schon sagte, geht es bei dieser Magie darum, Verbindungen aufzubauen und zu brechen. Wenn wir eine weitere Probe des Blutes finden könnten, könnten wir es gegen Azgaloths physische Form verwenden und ihn töten, um seine Seele ein für alle mal von Azeroth zu bannen.\n\nWie viel wisst Ihr über Bronzedrachen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85065] = { id = 85065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst merkwürdige Gnomin", description = "Was wir zum Abschluss dieser Mission brauchen, existiert genau hier in Andorhal, auch wenn es gerade nicht hier ist.\n\nIm Raum hinter mir befindet sich eine \"Gnomin\" namens Chromie. Sie ist eine recht kuriose Kreatur, die dafür bekannt ist, eine ganz besondere Form der Drachenmagie zu verwenden. Und zwar Zeitmagie.\n\nWenn wir sie überzeugen können, ihre Magie zu verwenden, um uns zu helfen, können wir vermutlich in der Zeit zurückreisen und holen, was wir brauchen. Es ist riskant, doch es ist möglicherweise unsere einzige Option. Schaut, ob Ihr sie überzeugen könnt, uns zu helfen.", sourceObjective = "Sprecht mit Chromie in Andorhal und überzeugt sie, Euch zu helfen.", completion = "Schön, Euch wiederzusehen, {name}! Zumindest meine ich, dass wir uns bereits begegnet sind. Das haben wir doch, oder? Es ist nicht gerade schwer, bei all den verschiedenen Versionen aller Personen durcheinanderzukommen, die ich so treffe... oder noch treffen werde.", sourceObjectiveStatus = "unverified-source-field" }
